_ACTIVE_BESS = None
if ENABLE_BESS:
    _ACTIVE_BESS = next((p for p in BESS_PROJECTS if p["name"] == ACTIVE_PROJECT), None)
    if _ACTIVE_BESS is None:
        raise RuntimeError("ACTIVE_PROJECT '%s' not in BESS_PROJECTS" % ACTIVE_PROJECT)
    ACTIVE_MW = _project_mw(_ACTIVE_BESS, ACTIVE_MW)
    # Enforce the per-feeder cap HERE, before anything else runs, so a bad project/MW
    # pairing fails immediately with a clear message instead of mid-build.
    for _cr in (_ACTIVE_BESS.get("member_rows") or [_ACTIVE_BESS]):
        _cmw = float(_cr.get("mw_together") or ACTIVE_MW or 0.0)
        _per_feeder = _cmw / max(1, len(_cr.get("feeders") or []))
        if _cr.get("feeders") and _per_feeder > FEEDER_MAX_MW + 1e-6:
            raise RuntimeError(
                "BESS %s: %g MW / %d feeder(s) = %.1f MW per feeder > FEEDER_MAX_MW=%g. "
                "Add feeders to the project entry or lower the MW."
                % (_cr.get("name"), _cmw, len(_cr["feeders"]), _per_feeder, FEEDER_MAX_MW))

# ---- STUDY DEFINITION ------------------------------------------------------
# >>> !!! CHANGE THESE TWO FOR THE DIS2301 PROJECT !!! They are the DIS2201 values and
#     nothing in the PQ .idv files identifies the new POI or project machines. Everything
#     else in this file is already switched over.
# ===========================================================================
# >>> PICK A PROJECT BY NAME. ITS POI AND ITS MACHINES FOLLOW AUTOMATICALLY.
# ---------------------------------------------------------------------------
# Straight out of BESS_PROJECTS above -- that list already carries every
# project's POI and its feeder buses, and the feeder buses ARE the machine
# buses. There is nothing to rediscover: set RUN_PROJECT and both POI_BUS and
# PROJECT_GENS follow.
#
# PROJECT_GEN_ID is the machine id on those buses. "1" is the existing plant;
# it becomes BESS_ID automatically when ENABLE_BESS adds new machines beside
# them. Give a project its own "gen_id" if one differs.
#
# A project can also carry an explicit "gens" list of (bus, id) pairs, which
# wins over the feeders -- for the case where a machine is not on the feeder
# bus, or a plant has more machines than feeders.
# ===========================================================================
RUN_PROJECT    = "IronStar"     # <<< SET ME: one of the BESS_PROJECTS names
# The launcher overrides this per project when RUN_PROJECTS names more than one.
# Editing the line above still works for a single run.
RUN_PROJECT    = (os.environ.get("SPP_PROJECT") or RUN_PROJECT).strip()
# The machine id on the feeder buses. "B" is what the BESS build wrote, and it
# stays "B" whether or not ENABLE_BESS is on NOW -- the machines are already in
# the case from that earlier run. Tying this to ENABLE_BESS was wrong: turning
# the BESS build off does not rename machines that are already there.
# If the id is ever wrong, the check at build time finds the bus's actual
# machine and uses it, rather than monitoring nothing.
PROJECT_GEN_ID = "B"

_RUN_PROJ = next((p for p in BESS_PROJECTS if p["name"] == RUN_PROJECT), None)
if _RUN_PROJ is None:
    raise RuntimeError("RUN_PROJECT %r is not in BESS_PROJECTS (%s)"
                       % (RUN_PROJECT, ", ".join(p["name"] for p in BESS_PROJECTS)))

POI_BUS      = int(_RUN_PROJ["poi"])
PROJECT_GENS = ([tuple(g) for g in _RUN_PROJ["gens"]] if _RUN_PROJ.get("gens")
                else [(int(b), PROJECT_GEN_ID) for b in _RUN_PROJ["feeders"]])
print("[init] project %s: POI %d, gens %s"
      % (RUN_PROJECT, POI_BUS, PROJECT_GENS))

#[  (587313, "1"), (587317, "1")]        # <<< SET ME: DIS2301 project machines
                           # G17-239-GEN2
if ENABLE_BESS:
    # The BESS study regulates the project's EXISTING POI and monitors the BESS machines.
    # Results go to their own folder so several projects (and MW levels) can run at once
    # without clobbering each other's outs/logs/plots/resume markers.
    POI_BUS      = _ACTIVE_BESS["poi"]
    PROJECT_GENS = [(b, BESS_ID) for b in _ACTIVE_BESS["feeders"]]
    RESULTS_DIR  = os.path.join(_results_root(),
                                "BESS_%s_%dMW" % (ACTIVE_PROJECT, ACTIVE_MW))
PROJECT_GEN_BUSES = [b for b, _ in PROJECT_GENS]   # auto-derived; do NOT edit

# ============================================================================
# EVERY PROJECT AT ONCE -- the helpers the rest of the file uses
# ============================================================================
# POI_BUS stays the FIRST member's POI so that everything written for one
# project keeps working; POI_BUSES is the list, and every distance, protect
# set, fault list, watch list and POI channel uses the list.
POI_BUSES = [int(x) for x in ((_RUN_PROJ.get("pois") if isinstance(_RUN_PROJ, dict) else None)
                              or [POI_BUS])]
if int(POI_BUS) not in POI_BUSES:
    POI_BUSES.insert(0, int(POI_BUS))
_HOLD_EXCLUDE_BUSES = set()      # every member's plant buses: never scaled by the area hold
# EVERY MEMBER'S POI, whichever member this study is focused on. The channel
# set is baked into the snapshot, and the member studies of a cluster SHARE
# one snapshot -- so all of them monitor the radius round every POI and name
# every POI channel by its bus. Faults, protect set and plots still follow
# POI_BUSES (the focus).
POI_BUSES_ALL = list(POI_BUSES)
try:
    if isinstance(_RUN_PROJ, dict) and _RUN_PROJ.get("member_rows"):
        POI_BUSES_ALL = [int(r["poi"]) for r in _RUN_PROJ["member_rows"]]
except Exception:
    pass


def _stamp_project():
    """The name the shared-build stamp carries: the cluster for a together
       run (every member study reuses the one snapshot), else the project."""
    _t = None
    for _r in (globals().get("_ACTIVE_BESS"), globals().get("_RUN_PROJ")):
        if isinstance(_r, dict) and _r.get("member_rows"):
            _t = _r
            break
    return (_t.get("cluster") or _t.get("name")) if _t else RUN_PROJECT
_MEMBER_ACTIVE = [None]          # the member a _member_scope is running, or None
_NP_BLOCK = None                 # (lo, hi) new-plant bus block of the member in scope


def _together_row():
    """The synthesised together row when this run is one, else None."""
    for _r in (globals().get("_ACTIVE_BESS"), globals().get("_RUN_PROJ")):
        if isinstance(_r, dict) and _r.get("member_rows"):
            return _r
    return None


def _poi_text():
    return str(POI_BUS) if len(POI_BUSES) <= 1 else ", ".join(str(p) for p in POI_BUSES)


def _poi_word():
    return "POI" if len(POI_BUSES) <= 1 else "nearest POI"


def _member_gens(row):
    """This member's machines as (bus, id): what the build made (gens_now),
       an explicit "gens" list, or its feeder buses with the project id."""
    if row.get("gens_now"):
        return [tuple(g) for g in row["gens_now"]]
    if row.get("gens"):
        return [tuple(g) for g in row["gens"]]
    _id = PROJECT_GEN_ID
    if globals().get("ENABLE_BESS") and globals().get("BESS_ID"):
        _id = globals().get("BESS_ID")
    return [(int(b), _id) for b in (row.get("feeders") or [])]


def _bess_members():
    """[(project row, MW)] to build and dispatch -- the members of a together
       run in order, or the one active project."""
    _t = _together_row()
    if _t:
        return [(r, float(r.get("mw_together") or r.get("mw") or 0.0))
                for r in _t["member_rows"]]
    _a = globals().get("_ACTIVE_BESS")
    return [(_a, globals().get("ACTIVE_MW"))] if _a else []


def _member_bus_owner():
    """{bus: member name} for a together run, else {}."""
    out = {}
    _t = _together_row()
    if not _t:
        return out
    for r in _t["member_rows"]:
        for b in (list(r.get("feeders") or []) + list(r.get("feeders_original") or [])
                  + [b for b, _m in _member_gens(r)]):
            out[int(b)] = r["name"]
        if r.get("poi") is not None:
            out[int(r["poi"])] = r["name"]
    return out


def _table_pick(val, name):
    """One member's value out of a per-project table; a plain value as is."""
    if not isinstance(val, dict):
        return val
    for k, v in val.items():
        if str(k).strip().lower() == str(name or "").strip().lower():
            if isinstance(v, (list, tuple, dict)):
                return v
            try:
                return float(v)
            except (TypeError, ValueError):
                return v
    return None


def _member_target(row):
    raw = globals().get("_POI_P_TARGET_RAW", globals().get("POI_P_TARGET_MW"))
    return _table_pick(raw, row.get("name"))


def _any_poi_target():
    raw = globals().get("_POI_P_TARGET_RAW", globals().get("POI_P_TARGET_MW"))
    if raw is None:
        return False
    if not isinstance(raw, dict):
        return True
    return any(_member_target(r) is not None for r, _mw in _bess_members())


def _np_member_file(name):
    return os.path.join(STUDY_DIR, CASE_TAG + "_newplant_buses_%s.txt"
                        % re.sub(r"[^A-Za-z0-9]+", "", str(name)))


def _np_member_index(row):
    _t = _together_row()
    if not _t:
        return 0
    for i, r in enumerate(_t["member_rows"]):
        if r is row or r.get("name") == row.get("name"):
            return i
    return 0


def _np_member_block(row):
    """The 10-bus block of NEW_PLANT numbers this member's units sit in."""
    if not _together_row():
        return None
    cfg = {}
    try:
        _fn = globals().get("_np_cfg")
        cfg = (_fn() if _fn else None) or dict(globals().get("NEW_PLANT") or {})
    except Exception:
        cfg = {}
    b0 = int(cfg.get("bus_start") or 900001) + 10 * _np_member_index(row)
    return (b0, b0 + 9)


def _np_member_cfg(cfg, row):
    """NEW_PLANT for one member of a together run: its own bus block (10 apart,
       units/GSU/collector/HV each 100 apart as before) and its own name."""
    if not _together_row() or not cfg:
        return cfg
    c = dict(cfg)
    c["bus_start"] = int(cfg.get("bus_start") or 900001) + 10 * _np_member_index(row)
    c["name"] = str(row.get("name") or cfg.get("name") or "NEWGEN")
    return c


def _hold_rows():
    """One pseudo-row per member AREA for the area hold after the solve: the
       area, and every member's plant buses as the set never to scale."""
    _t = _together_row()
    if not _t:
        return [globals().get("_ACTIVE_BESS")]
    _allf = set(int(b) for b in _HOLD_EXCLUDE_BUSES)
    for r in _t["member_rows"]:
        for b in list(r.get("feeders") or []) + list(r.get("feeders_original") or []):
            _allf.add(int(b))
    seen, out = [], []
    for r in _t["member_rows"]:
        a = r.get("area")
        if a is None or a in seen or _member_target(r) is None:
            continue
        seen.append(a)
        out.append({"name": "%s (area %s)" % (_t["name"], a), "area": a,
                    "feeders": sorted(_allf), "feeders_original": []})
    return out


class _member_scope(object):
    """Run one member's build/dispatch step with the module globals pointed at
       THAT member: its MW, its POI, its machines, its POI target, its
       new-plant record file and bus block. Everything is restored on exit and
       the union (PROJECT_GENS, PROJECT_GEN_BUSES, the row's feeders) is
       re-derived from the members. A no-op for a single-project run."""
    _KEYS = ("ACTIVE_MW", "ACTIVE_PROJECT", "RUN_PROJECT", "POI_BUS", "POI_BUSES",
             "PROJECT_GENS", "PROJECT_GEN_BUSES", "POI_P_TARGET_MW",
             "POI_P_EXISTING_BUSES", "NEW_PLANT_BUSES_FILE", "_NP_BLOCK", "_POI_HOPS")

    def __init__(self, row, mw):
        self.row, self.mw, self.saved = row, mw, {}
        self.together = False

    def __enter__(self):
        g = globals()
        self.together = bool(_together_row()) and isinstance(self.row, dict)
        for k in self._KEYS:
            self.saved[k] = g.get(k)
        if not self.together:
            return self.row
        r = self.row
        g["ACTIVE_MW"] = self.mw
        g["ACTIVE_PROJECT"] = r["name"]
        g["RUN_PROJECT"] = r["name"]
        g["POI_BUS"] = int(r["poi"])
        g["POI_BUSES"] = [int(r["poi"])]
        g["PROJECT_GENS"] = _member_gens(r)
        g["PROJECT_GEN_BUSES"] = [b for b, _m in g["PROJECT_GENS"]]
        g["POI_P_TARGET_MW"] = _member_target(r)
        _eb = _table_pick(g.get("_POI_P_EXIST_RAW", g.get("POI_P_EXISTING_BUSES")), r["name"])
        g["POI_P_EXISTING_BUSES"] = list(_eb) if isinstance(_eb, (list, tuple)) else []
        if g.get("NEW_PLANT_BUSES_FILE"):
            g["NEW_PLANT_BUSES_FILE"] = _np_member_file(r["name"])
        g["_NP_BLOCK"] = _np_member_block(r)
        g["_POI_HOPS"] = None
        _MEMBER_ACTIVE[0] = r["name"]
        print("  [together] --- %s: %g MW at POI %d%s ---"
              % (r["name"], float(self.mw or 0), int(r["poi"]),
                 (", POI total %s MW" % g["POI_P_TARGET_MW"])
                 if g["POI_P_TARGET_MW"] is not None else ""))
        return r

    def __exit__(self, *a):
        g = globals()
        if self.together:
            self.row["gens_now"] = [tuple(x) for x in (g.get("PROJECT_GENS") or [])]
            for b, _m in self.row["gens_now"]:
                _HOLD_EXCLUDE_BUSES.add(int(b))
            for b in (self.row.get("feeders") or []):
                _HOLD_EXCLUDE_BUSES.add(int(b))
        for k, v in self.saved.items():
            g[k] = v
        _MEMBER_ACTIVE[0] = None
        if self.together:
            _t = _together_row()
            gens = []
            for r in _t["member_rows"]:
                for x in _member_gens(r):
                    if tuple(x) not in gens:
                        gens.append(tuple(x))
            g["PROJECT_GENS"] = gens
            g["PROJECT_GEN_BUSES"] = [b for b, _m in gens]
            feed = []
            for r in _t["member_rows"]:
                for b in (r.get("feeders") or []):
                    if int(b) not in feed:
                        feed.append(int(b))
            _t["feeders"] = feed
            _t["disable_existing"] = bool(any(r.get("disable_existing")
                                              for r in _t["member_rows"]))
            g["_POI_HOPS"] = None
        return False


if _together_row():
    for _r in _together_row()["member_rows"]:
        for _b in (list(_r.get("feeders") or []) + list(_r.get("feeders_original") or [])
                   + [b for b, _m in _member_gens(_r)]):
            _HOLD_EXCLUDE_BUSES.add(int(_b))


def _poi_ties_all(feeders):
    """The interconnection tie branches of every POI of this run."""
    _t = _together_row()
    if not _t:
        return list(_poi_tie_branches(feeders, POI_BUS))
    out = []
    for r in _t["member_rows"]:
        try:
            for x in _poi_tie_branches([b for b, _m in _member_gens(r)]
                                       or list(r.get("feeders") or []), int(r["poi"])):
                if x not in out:
                    out.append(x)
        except Exception:
            pass
    return out


def _delivered_all(feeders):
    """(P, Q) delivered into the POI(s): summed over the members of a together run."""
    _t = _together_row()
    if not _t:
        return _delivered_to_poi(feeders, POI_BUS)
    P = Q = 0.0
    for r in _t["member_rows"]:
        p, q = _delivered_to_poi([b for b, _m in _member_gens(r)]
                                 or list(r.get("feeders") or []), int(r["poi"]))
        P += float(p or 0.0)
        Q += float(q or 0.0)
    return P, Q


def _hops_from_all(max_hops=None):
    """{bus: hops from the NEAREST POI} on the fault-list topology."""
    out = {}
    for _pb in POI_BUSES:
        for b, h in hops_from(_pb, max_hops).items():
            if b not in out or h < out[b]:
                out[b] = h
    return out


def _sf_hop_map_all(max_hops):
    out = {}
    for _pb in POI_BUSES:
        for b, h in (sf_hop_map(_pb, max_hops) or {}).items():
            if b not in out or h < out[b]:
                out[b] = h
    return out


def _sf_fault_sig(f):
    """What makes two generated faults the same event, whichever POI they were
       built around: type, faulted bus, planning event, what is tripped, timing."""
    def _n(v):
        try:
            return int(v)
        except (TypeError, ValueError):
            return str(v)
    trips = []
    for k in ("trip_lines", "trip_xfmrs", "trip_machines", "trip_buses", "trips",
              "trip_branches", "trip_gens"):
        for t in (f.get(k) or []):
            if isinstance(t, (list, tuple)):
                trips.append(tuple(str(x) for x in t))
            else:
                trips.append((str(t),))
    return (str(f.get("type")), _n(f.get("fault_bus")), str(f.get("planning_event")),
            tuple(sorted(trips)),
            str(f.get("cycles") or f.get("clear_cycles") or f.get("duration") or ""))


def _sf_build_all_pois(hops, kv_min):
    """The SPP list around EVERY POI of this run -- one build per POI, merged
       without repeats, numbered F01.. in POI order. With one POI this is
       exactly sf_build_spp_faults."""
    if len(POI_BUSES) <= 1:
        sf_diagnose_poi(POI_BUS)
        return sf_build_spp_faults(POI_BUS, hops, kv_min)
    out, seen, per = [], set(), []
    for _k, _pb in enumerate(POI_BUSES, 1):
        print("")
        print("[spp-faults] ===== POI %d of %d: %s =====" % (_k, len(POI_BUSES), _pb))
        sf_diagnose_poi(_pb)
        got = sf_build_spp_faults(_pb, hops, kv_min) or []
        n_new = 0
        for f in got:
            key = _sf_fault_sig(f)
            if key in seen:
                continue
            seen.add(key)
            f["poi"] = int(_pb)
            out.append(f)
            n_new += 1
        per.append("POI %s: %d built, %d new" % (_pb, len(got), n_new))
    for i, f in enumerate(out, 1):
        f["id"] = "F%02d" % i
    print("[spp-faults] together: %d fault(s) around %d POI(s) after removing repeats (%s)"
          % (len(out), len(POI_BUSES), "; ".join(per)))
    return out
