FDNS_OPTS = [0, 0, 0, 1, 1, 0, 0, 0]   # = the PQ Run1-create-snap.idv exactly
# ---- robust convergence (for var-limit / switched-shunt HUNTING) -----------
# FDNS can hunt (oscillate) on big MMWG cases with wind var-limit control. If it
# doesn't converge, we polish with FULL Newton (FNSL). PF_LOCK_OPTS first LOCKS the
# discrete devices (switched shunts + taps off) with var limits ON to kill the
# limit-cycle, then FNSL_OPTS re-solves with normal controls. options list =
# [TAPS, AREAINT, PHASE, DCTAP, SWSHUNT, FLATSTART, VARLIM, NONDIVERGENT].
FNSL_OPTS     = [0, 0, 0, 1, 1, 0, 0, 0]   # full-Newton polish with the SAME controls as the idv FDNS
PF_LOCK_OPTS  = [0, 0, 1, 1, 0, 0, 0, 0]   # anti-hunting pass: DISCRETE devices locked ON PURPOSE
                                           # (taps=0 locked, switched shunts=0 locked) -- this one is
                                           # deliberately NOT the GUI settings; it exists to break a limit cycle.
PF_MAX_POLISH = 4                          # full-Newton polish passes to attempt

