# ============================================================================
# >>> PARALLEL EXECUTION (multi-process). PSS/E has ONE global engine per process, so
#     "parallel" means several PROCESSES -- each its own PSS/E session -- each running a
#     DIFFERENT slice of the fault set. Controlled by env vars that the launcher
#     (run_study_parallel.py) sets; run this script DIRECTLY with none of them set and it
#     behaves EXACTLY as before (role "all": build + flat + every fault + merged report).
#       SPP_ROLE = "all"    single process: build + flat + all faults + report (default)
#                  "build"  build snapshot + generate fault set + flat run, then STOP
#                  "work"   reuse snapshot; run ONLY faults[SPP_WORKER::SPP_N_WORKERS]
#                  "report" run nothing; read every finished .out and write ONE merged report
#       SPP_N_WORKERS  total number of worker processes (>=1)
#       SPP_WORKER     this worker's index, 0 .. N-1
# ============================================================================
SPP_ROLE     = os.environ.get("SPP_ROLE", "all").strip().lower()
N_WORKERS    = max(1, int(os.environ.get("SPP_N_WORKERS", "1") or "1"))
WORKER_INDEX = max(0, int(os.environ.get("SPP_WORKER", "0") or "0"))
# per-role/-worker suffix so parallel processes NEVER share a log file or resume sentinel
if   SPP_ROLE == "all":  _WSUF = ""
elif SPP_ROLE == "work": _WSUF = "_w%d" % WORKER_INDEX
elif SPP_ROLE == "report" and N_WORKERS > 1:
    # A SHARDED REPORT IS N PROCESSES, ALL WITH SPP_ROLE=report. Without the
    # index they would every one of them use "_report" and so open the SAME
    # DYN_STUDY_report.log, DYN_STUDY_EVENTS_report.log, PROGRESS_report.csv and
    # PSS/E sink -- six processes writing one file on Windows, which is at best
    # interleaved nonsense and at worst a sharing violation that kills a shard.
    _WSUF = "_report_w%d" % WORKER_INDEX
else:                    _WSUF = "_" + SPP_ROLE          # _build / _report / merge
# THE PLOT PASS HAS ITS OWN LOG. It inherits whatever role its environment
# carries -- "build", as it turned out -- and wrote over DYN_STUDY_build.log,
# so the record of what the build did to the deck was gone by the time anyone
# asked. A plotter's log is named for what it is.
if (os.environ.get("SPP_PLOT_MISSING") or "").strip():
    _WSUF = "_plot%s" % (("_s" + (os.environ.get("SPP_PLOT_SLOT") or "0").strip())
                         if (os.environ.get("SPP_PLOT_SLOT") or "").strip() else "")

# >>> RUN ONLY SELECTED FAULTS ------------------------------------------------
# SPP_ONLY names the scenarios to run, taken from the fault definition file
# (results\dynamics\faults\SPP_FAULTS.csv). The launcher sets it from its own
# RUN_ONLY_FAULTS list; you can also set it by hand:
#     set SPP_ONLY=F01                 one fault
#     set SPP_ONLY=F01,F07,F19         several
#     set SPP_ONLY=F19-F24             a range (expands to F19 F20 F21 F22 F23 F24)
#     set SPP_ONLY=FLAT_RUN            the flat case
#     set SPP_ONLY=                    cleared -- normal full run
#
# For the named ids ONLY, the .done marker and the MAX_SCENARIO_ATTEMPTS
# give-up limit are IGNORED, so a fault that already finished (or already
# crashed five times) will actually re-run. Every other scenario is skipped and
# the snapshot is reused, so a selective run starts in seconds.
def _expand_ids(text):
    """'F01,F19-F21' -> ['F01','F19','F20','F21']. Ranges need a common prefix
       and equal-width numbers, which is how the generated ids are formed."""
    out = []
    for tok in str(text).replace(";", ",").split(","):
        tok = tok.strip().upper()
        if not tok:
            continue
        if "-" in tok and tok.count("-") == 1:
            lo, hi = [t.strip() for t in tok.split("-")]
            pre = "".join(c for c in lo if not c.isdigit())
            lo_n, hi_n = lo[len(pre):], hi[len(pre):] if hi.startswith(pre) else hi
            if pre and lo_n.isdigit() and hi_n.isdigit():
                w = len(lo_n)
                for n in range(int(lo_n), int(hi_n) + 1):
                    out.append("%s%0*d" % (pre, w, n))
                continue
        out.append(tok)
    seen, uniq = set(), []
    for s in out:
        if s not in seen:
            seen.add(s); uniq.append(s)
    return uniq


ONLY_SCENARIOS = _expand_ids(os.environ.get("SPP_ONLY", ""))

# "if-missing" (default) rewrite the fault files only when SPP_FAULTS.csv is absent
# "always"                rewrite them on every run
# "never"                 only the build process ever writes them (the old behaviour)
REGEN_FAULT_FILES = (os.environ.get("SPP_REGEN_FAULTS", "") or "if-missing").strip().lower()
if REGEN_FAULT_FILES in ("1", "true", "yes", "on"):
    REGEN_FAULT_FILES = "always"
if REGEN_FAULT_FILES in ("0", "false", "no", "off"):
    REGEN_FAULT_FILES = "never"

# Own log + own resume sentinel for a hand-run selective job, so it cannot
# overwrite DYN_STUDY.log nor drop a flag that stops the launcher relaunching.
#
# NOT under 'work' or 'report': THE LAUNCHER OWNS THOSE NAMES.
#
# It used to apply to 'report' too, and that broke the sharded report outright.
# The launcher reads REPORT_STATUS_report_w0.txt, but a shard with SPP_ONLY set
# wrote
#     REPORT_STATUS_report_w0_only_F03_F04_F05_F06_F07_F08_F09_F1.txt
# so the status was never found and the progress line said "starting" for the
# whole run while the shard was working perfectly. It mangled
# DYN_STUDY_report_w<i>.log the same way, which is why those logs were not
# where they should have been either.
#
# A hand-run job -- role 'all' -- still gets its own suffix, which is what this
# was for.
if ONLY_SCENARIOS and SPP_ROLE not in ("work", "report"):
    _WSUF += "_only_" + "_".join(ONLY_SCENARIOS)[:40]




# ---- SELECT BY PLANNING EVENT ----------------------------------------------
# SPP_ONLY_EVENTS names planning events instead of fault ids:
#     set SPP_ONLY_EVENTS=P1.2            only the 3ph line faults
#     set SPP_ONLY_EVENTS=P1.2,P1.3       lines and transformers
#     set SPP_ONLY_EVENTS=P1              every P1 sub-event
#     set SPP_ONLY_EVENTS=P6
#
# This is a DIFFERENT question from SPP_EVENTS in the study settings. SPP_EVENTS
# decides which events are GENERATED into the fault list; this decides which of
# the events already in the list are run or scored. Turning P4.2 off in
# SPP_EVENTS and regenerating destroys the P4.2 results; selecting P1.2 here
# leaves them alone and runs the subset.
ONLY_EVENTS = [x.strip().upper()
               for x in (os.environ.get("SPP_ONLY_EVENTS") or "").replace(";", ",").split(",")
               if x.strip()]
_ONLY_EVENTS_APPLIED = False


def _event_match(pe, toks):
    """P1 matches P1.2; P1.2 matches only P1.2.

       A bare family has to select its sub-events or "run the P1 set" would
       select nothing, which reads as "there are no P1 faults"."""
    pe = (pe or "").strip().upper()
    for t in toks:
        if pe == t or pe.startswith(t + "."):
            return True
    return False


def _apply_only_events():
    """Turn SPP_ONLY_EVENTS into ids and fold them into ONLY_SCENARIOS.

       Read from the fault list this study runs, so the ids are the ones on disk
       rather than this process's idea of what the generator would produce."""
    global ONLY_SCENARIOS, _ONLY_EVENTS_APPLIED
    if _ONLY_EVENTS_APPLIED or not ONLY_EVENTS:
        return
    _ONLY_EVENTS_APPLIED = True
    p = os.path.join(FAULTS_DIR, "SPP_FAULTS.csv")
    ids, seen_ev = [], set()
    try:
        with open(p, newline="") as fh:
            for r in csv.DictReader(fh):
                pe = (r.get("planning_event") or "").strip()
                fid = (r.get("fault_id") or "").strip()
                if pe:
                    seen_ev.add(pe.upper())
                if fid and _event_match(pe, ONLY_EVENTS):
                    ids.append(fid.upper())
    except Exception as e:
        print("[only-events] could not read %s (%s) -- event selection SKIPPED" % (p, e))
        return
    if not ids:
        # SELECTING NOTHING IS NOT THE SAME AS SELECTING EVERYTHING, and an
        # EMPTY ONLY_SCENARIOS means "run everything" everywhere below. Leaving
        # it empty here would turn "run only the P7 faults" -- of which there
        # are none -- into a full 138-scenario run. The sentinel matches no id,
        # so nothing runs and the message above says why.
        print("*** [only-events] %s matched NO fault in %s"
              % (", ".join(ONLY_EVENTS), p))
        print("    the list holds these planning events: %s"
              % (", ".join(sorted(seen_ev)) or "(none recorded)"))
        print("    selecting NOTHING rather than everything.")
        ONLY_SCENARIOS = ["__NO_SUCH_EVENT__"]
        return
    if ONLY_SCENARIOS:
        keep = [x for x in ONLY_SCENARIOS if x in set(ids)]
        print("[only-events] %s + the id selection -> %d scenario(s)"
              % (", ".join(ONLY_EVENTS), len(keep)))
        # Same trap: an id selection that shares nothing with the event
        # selection is an empty intersection, not an invitation to run the lot.
        ONLY_SCENARIOS = keep or ["__NO_SUCH_EVENT__"]
    else:
        print("[only-events] %s -> %d scenario(s): %s"
              % (", ".join(ONLY_EVENTS), len(ids),
                 ", ".join(ids[:12]) + (" ..." if len(ids) > 12 else "")))
        ONLY_SCENARIOS = ids


# True when SPP_ONLY already holds THIS WORKER'S share, set by the launcher.
# The launcher deals the selected ids out round-robin and gives each worker its
# own list; slicing that list again by worker index keeps only the overlap,
# which is about a third of it.
ONLY_PRESLICED = (os.environ.get("SPP_ONLY_PRESLICED") or "").strip() in ("1", "true", "yes", "on")


def _only_mode():
    """True when this process was told to run a specific subset."""
    return bool(ONLY_SCENARIOS)


def _wanted(scen_id):
    """True if this scenario should run. Always True when SPP_ONLY is unset.

       Matched on the WHOLE id, or on its leading token. An spp id is just
       "F03", but a custom one is "C01_3PH_765911_10cy" -- the bus and the
       clearing time are part of the name -- so exact matching made
       RUN_ONLY_FAULTS = ["C01-C12"] select nothing, having expanded to exactly
       the ids C01..C12 that no custom scenario is called. The leading token is
       the id; the rest of the name says what it is."""
    if not ONLY_SCENARIOS:
        return True
    sid = str(scen_id).strip().upper()
    if sid in ONLY_SCENARIOS:
        return True
    head = sid.split("_", 1)[0]
    return bool(head) and head != sid and head in ONLY_SCENARIOS
# Your RUN1C1.IDV runs FDNS once and proceeds WITHOUT checking convergence. FDNS
# often returns solved=1 (iteration limit) on big MMWG/SPP cases yet still builds a
# usable snapshot. So the build only WARNS on non-convergence by default (and
# retries FDNS once). Set True if you want the build to hard-stop instead.
ABORT_ON_PF_NONCONV = True

# ---- timing (s) -----------------------------------------------------------
FREQ_HZ     = 60.0
FLAT_RUN_S  = 5         # >>> the PQ Run3 idv ends with "RUN,cm  20.1" -- match it

# >>> OVERRIDABLE FROM THE ENVIRONMENT, so z4_cmp_all_con.py sets the simulation
# lengths for BOTH cases from one place. They have to match: a fault run to 10 s
# in one case and 20 s in the other is not a comparison -- the longer run has
# more time to recover, or to fall over, and nothing in the report would say the
# two were judged over different windows.
#     set SPP_FLAT_RUN_S=5
#     set SPP_SIM_END_S=10
# ---- SETTINGS THIS FILE ACCEPTS FROM z4_cmp_all_con.py ---------------------------
# z4_cmp_all_con.py owns the settings that must be the SAME IN BOTH CASES, and sends
# them in the environment. A variable that is not set leaves the value in this
# file alone, so running a study directly still behaves exactly as written here.
def _env_str(name, default):
    v = (os.environ.get(name) or "").strip()
    return v if v else default


def _env_num(name, default):
    v = (os.environ.get(name) or "").strip()
    if not v:
        return default
    try:
        return int(v) if re.match(r"^-?\d+$", v) else float(v)
    except ValueError:
        return default


def _env_bool(name, default):
    v = (os.environ.get(name) or "").strip().lower()
    if not v:
        return default
    return v in ("1", "true", "yes", "on")


def _env_list(name, default):
    v = (os.environ.get(name) or "").strip()
    if not v:
        return default
    return [x.strip() for x in v.split(",") if x.strip()]


def _env_float(name, default):
    v = (os.environ.get(name) or "").strip()
    if not v:
        return default
    try:
        f = float(v)
    except ValueError:
        print("[sim] %s=%r is not a number -- keeping %s" % (name, v, default))
        return default
    if f <= 0:
        print("[sim] %s=%s is not positive -- keeping %s" % (name, v, default))
        return default
    return f


FLAT_RUN_S = _env_float("SPP_FLAT_RUN_S", FLAT_RUN_S)
PRE_FAULT_S = 5.0           # >>> seconds of steady state BEFORE applying a fault
PRE_FAULT_S = _env_float("SPP_PRE_FAULT_S", PRE_FAULT_S)
SIM_END_S   = 10.0         # >>> total sim length for each fault (post-fault recovery)
SIM_END_S = _env_float("SPP_SIM_END_S", SIM_END_S)
if (os.environ.get("SPP_FLAT_RUN_S") or os.environ.get("SPP_SIM_END_S")
        or os.environ.get("SPP_PRE_FAULT_S")):
    print("[sim] durations from the environment: flat %.2f s, pre-fault %.2f s, "
          "fault run %.2f s" % (FLAT_RUN_S, PRE_FAULT_S, SIM_END_S))
if PRE_FAULT_S >= SIM_END_S:
    # THE FAULT WOULD BE APPLIED AT OR AFTER THE END OF THE RUN. Nothing later
    # checks this: the run would simply stop before the disturbance, write a
    # flat .out, and be scored as a scenario that rode through perfectly.
    print("*** [sim] PRE_FAULT_S (%.2f s) is not before SIM_END_S (%.2f s) -- the "
          "fault would never be applied" % (PRE_FAULT_S, SIM_END_S))
    raise SystemExit(2)

# ---- run() reporting / plotting cadence -----------------------------------
# psspy.run(option, tpause, NPRT, NPLT, CRTPLT):
#   NPRT = steps between PSS/E's *formatted text* progress reports.
#   NPLT = steps between writes to the binary channel .out file (plot resolution).
# The forrtl severe(66) "output statement overflows record" crash at fault time is the
# FORMATTED progress report (NPRT) choking on a channel value that spikes to a huge/Inf
# number the instant the fault hits (IBR QELEC surge, bus df/dt, etc.). Setting NPRT=0
# turns that text report OFF -> no formatted write -> no overflow. Channels are still
# fully recorded in the .out (that's NPLT), so plots/reports are unaffected.
RUN_NPRT = 0               # 0 = progress report OFF (prevents forrtl-66 overflow). Keep 0.
RUN_NPLT = 2               # write channels every N steps. 1=every step (huge .out/CSV);
# HOW BIG THE .out IS, AND HOW LONG IT TAKES TO SCORE. With ~7,800 channels,
# DELT = 1/4 cycle and a 30.2 s run, NPLT = 2 samples every 0.0083 s and
# writes 113 MB per scenario -- which then has to be read back and scored.
# NPLT = 8 samples every 0.033 s (2 cycles), which is ample for voltage
# recovery over 2.5 s and for rotor-angle swings, and makes it 28 MB.
# Settable from z4_cmp_all_con.py so both cases get the same resolution.
                           # 2 halves the file with no visible loss for a 30 s plot.

# >>> DIAGNOSTIC LOG FOR PSS/E SUPPORT ---------------------------------------
# The normal run HIDES PSS/E's own progress: strt_2 progress goes to a separate buffered
# file (lost on a hard crash), per-step run progress is OFF (RUN_NPRT=0), and the fault
# window is silenced. Great for clean logs, useless for a crash report -- the log just
# "stops after initial suspect". Set DIAG_SUPPORT_LOG=True to capture EVERYTHING PSS/E
# prints, live, into the MAIN per-worker log (DYN_STUDY[_wN].log), flushed line-by-line so
# the LAST operation before the crash survives. It does this by:
#   * keeping PSS/E progress on device 1 (the tee'd, flushed stdout) instead of a buffered file
#   * turning per-step run progress ON (RUN_NPRT_DIAG below)
#   * disabling the fault-window silencing (so the crash-time output is not discarded)
# COST: much larger/slower log, and enabling progress MAY itself change/trigger the
# forrtl-66 path -- that is fine when the goal is to reproduce+capture the crash for support.
# HOW TO USE: set True, run the ONE crashing scenario (e.g. run the study directly, or let
# the parallel worker hit it), then send the resulting logs\DYN_STUDY*.log to PSS/E support.
DIAG_SUPPORT_LOG = False
RUN_NPRT_DIAG    = 100     # with DIAG_SUPPORT_LOG: emit a PSS/E progress report every N steps

# >>> LIVE SIM-CLOCK PROGRESS: print "sim t = X / total s" during each run so you can
# see how far the simulation has advanced (each psspy.run is otherwise one silent
# blocking call to the end time). Set SHOW_SIM_PROGRESS=False to go back to a single
# blocking run. PROGRESS_STEP_S = how often (in SIMULATED seconds) to print a line.
SHOW_SIM_PROGRESS = True    # print the simulation clock as the run advances
PROGRESS_STEP_S   = 0.5     # seconds of SIMULATED time between progress prints

# A chunk of simulated time can take MINUTES of wall clock on a case this size --
# one scenario ran 85 minutes for 10 simulated seconds. Between chunks nothing is
# printed, and a worker that prints nothing is indistinguishable from one that
# has hung: the launcher's watchdog eventually kills it, and the scenario is
# recorded as having given up when it was working the whole time. This prints
# from a background thread WHILE psspy.run is blocked, so there is always
# something on the console and the watchdog always sees activity.
RUN_HEARTBEAT_S = 60        # wall-clock seconds between "still solving" lines (0 = off)

# ---- dynamics solution parameters -----------------------------------------
# RUN1 build : ACCEL 0.60, TOL 0.0001,     DELT 0.0041667
# RUN3 init  : ACCEL 0.60, TOL 0.0000095,  DELT 0.0041667   (Run3-NoFault-qc / RUN3N.idv)
SOLV_NITER      = 60        # MAXITER -- both PQ idvs say 60
SOLV_ACCEL      = 0.60      # BUILD network-solution acceleration (PQ Run1 idv: 0.60)
SOLV_ACCEL_INIT = 0.60      # INIT  network-solution acceleration (PQ Run3 idv: 0.60)
# If strt_2 struggles to converge the t=0 network solve on this case (symptom: it stalls
# or produces garbage initial conditions), raise SOLV_NITER to 200 and drop
# SOLV_ACCEL_INIT to 0.30 -- that combination fixed exactly that on the CQ case.
SOLV_TOL        = 0.0001    # BUILD network-solution tolerance
SOLV_TOL_INIT   = 0.0000095 # INIT  network-solution tolerance (Run3)
SOLV_DELT       = 1.0 / (FREQ_HZ * 4.0)   # DELT = 1/4 cycle = 0.0041667 s
# FROM THE PANEL: DELT_CYCLES in z4_cmp_all_con.py (4 = quarter cycle, the PQ idv
# value; 8 = eighth cycle). A case whose network solution loses itself in the
# fault -- NaN in the fault runs while the flat run is clean -- often holds at
# the smaller step, at twice the run time. Applied at the build and at every
# scenario's initialisation, so it takes effect without a rebuild.
try:
    _dc = float(os.environ.get("SPP_DELT_CYCLES") or 0)
    if _dc > 0:
        SOLV_DELT = 1.0 / (FREQ_HZ * _dc)
        print("[solver] DELT = 1/%g cycle = %.6f s (DELT_CYCLES from z4_cmp_all_con.py)" % (_dc, SOLV_DELT))
except (TypeError, ValueError):
    pass
SOLV_FREQFILTER = 0.033333

# >>> AUTO-RETRY A NON-CONVERGED SCENARIO WITH DIFFERENT SOLVER SETTINGS ---------
# PSS/E prints, per non-converged step:
#   "<n>S-Network not converged at TIME = <t>  <iters>  <mismatch>  <bus> [name] ..."
# When SOLVER_RETRY_ON_NONCONV is on, a scenario that produces more than
# SOLVER_RETRY_MAX_NONCONV such steps is RE-RUN from the top with the next recipe in
# SOLVER_RETRY_RECIPES, until one converges or the list runs out. Whatever finally
# worked is printed and recorded in RUN_SUMMARY, so the settings that fixed each
# scenario are part of the study record instead of being lost in the scrollback.
#
# Each recipe is (label, MAXITER, ACCEL). ONLY those two are ever touched -- the
# tolerance and the time step keep the values the .idv sets, so a scenario that is
# retried is still solved to the same accuracy on the same time step as every other
# one. None = leave that parameter as it is.
# Order matters: cheapest and least intrusive first.
SOLVER_RETRY_ON_NONCONV  = False
SOLVER_RETRY_MAX_NONCONV = 4      # non-converged steps tolerated before a retry is triggered
SOLVER_RETRY_RECIPES = [
    ("iterations 200",              200, None),
    ("iterations 200, accel 0.50",  200, 0.50),
    ("iterations 400, accel 0.30",  400, 0.30),
    ("iterations 400, accel 0.20",  400, 0.20),
    ("iterations 600, accel 0.10",  600, 0.10),
]
# ---- AND THE SAME THREE, FROM THE PANEL ------------------------------------
# SPP's fourth system adjustment is "acceleration factors of multiple faults
# were adjusted", and this is the mechanism for it -- but adjusting the solver
# under a scenario that will not converge is a decision about the study, not a
# convenience, so it is OFF unless z4_cmp_all_con.py turns it on. A run that quietly
# re-solved its hard events on different settings and reported them beside the
# ones that converged first time would be presenting two different studies as
# one.
#
# NOTE ON THE FIRST RECIPE. Attempt one uses SOLVER_RETRY_RECIPES[0], not the
# case's own parameters -- so with the list below every scenario of a run with
# retries on is solved at 200 iterations, and 60 is never tried. That is
# deliberate (the cheapest recipe first), and it is why the list starts with the
# mildest change there is. Put (None, None) first if you want the case's own
# settings to be attempt one.
SOLVER_RETRY_ON_NONCONV = _env_bool("SPP_SOLVER_RETRY", SOLVER_RETRY_ON_NONCONV)
SOLVER_RETRY_MAX_NONCONV = int(_env_num("SPP_SOLVER_RETRY_MAX",
                                        SOLVER_RETRY_MAX_NONCONV))
_srr = (os.environ.get("SPP_SOLVER_RETRY_RECIPES") or "").strip()
if _srr:
    try:
        import json as _json
        # (label, MAXITER, ACCEL). None for either number leaves that parameter
        # alone, and JSON writes it as null, so it survives the trip intact.
        SOLVER_RETRY_RECIPES = [(str(r[0]),
                                 None if r[1] is None else int(r[1]),
                                 None if r[2] is None else float(r[2]))
                                for r in _json.loads(_srr)]
        print("[solver] retry ladder from the panel: %s"
              % ", ".join(r[0] for r in SOLVER_RETRY_RECIPES))
    except Exception as _e:
        print("[solver] SPP_SOLVER_RETRY_RECIPES could not be read (%s) -- "
              "the study's own ladder is used" % _e)
if SOLVER_RETRY_ON_NONCONV:
    print("[solver] non-converged scenarios WILL be re-run on other solution "
          "settings (%d recipe(s), more than %d non-converged step(s) triggers "
          "it). Which recipe fixed which event is in the run summary and in the "
          "SYSTEM ADJUSTMENTS section."
          % (len(SOLVER_RETRY_RECIPES), SOLVER_RETRY_MAX_NONCONV))

# Filled in as the study runs: scen_id -> (recipe label, non-converged steps remaining)
SOLVER_FIX = {}
# AND WHAT EVERY SCENARIO WAS SOLVED ON -- not only the ones that needed a
# retry. With the ladder on, attempt one already runs on its first recipe, so
# "no solver_fix" did not mean "the case's own settings"; it meant the first
# recipe, silently. scen_id -> label of the settings the kept attempt used.
SOLVER_USED = {}

# >>> Monitoring scan switches (BAT_SET_* in RUN3N.idv).
# >>> Straight from the PQ Run3-NoFault-qc.idv. The CQ version had every scan DISABLED
#     (status 0); the PQ idv turns them ON, so they are on here.
SCAN_NETFRQ  = 1                  # BAT_SET_NETFRQ 1
SCAN_OSSCAN  = (1, 0)             # BAT_SET_OSSCAN 1, 0        (scan on, do NOT trip)
SCAN_GENANG  = (1, 2400000.00)    # BAT_SET_GENANG 1, 2400000
SCAN_GENPWR  = (1, 1.100)         # BAT_SET_GENPWR 1, 1.100
SCAN_VLTSCN  = (1, 1.2000, 0.7000)# BAT_SET_VLTSCN 1, 1.2, 0.7
SCAN_RELSCN  = 0                  # BAT_SET_RELSCN 0
SCAN_RELANG  = (1, RELANG_REF_BUS, "1")   # BAT_SET_RELANG 1, 364003, '1'  (was 0 in the CQ version)

# >>> Machines to REMOVE (set out-of-service) at BUILD time. The COMPCC pair at bus
# 652549 has one unit out-of-service, so PSS/E prints '** Model ignored **' -- leaving
# a machine in the swing tables with never-integrated (garbage) states. The first
# swing-capture sweep after ANY disturbance formats those states and overflows the
# writer (forrtl-66 in SWCAPT/TBLCNC). The pair is in a different region (study areas
# untouched). NOTE: applied during BUILD -- set BUILD_SNAPSHOT=True (or delete the
# .cnv/.snp) once so the snapshot is rebuilt without them.
# >>> MASTER SWITCH for the machine removals below. These machines are switched OUT OF SERVICE
#     during BUILD, BEFORE the power flow is solved -- so the script solves a DIFFERENT case than
#     the GUI does (generation shifts to the swing bus), which can change convergence.
#     Set False to keep every machine in service and solve exactly the case the GUI solves.
#     CAUTION: they were removed because their DYNAMIC models are broken (missing DLL / "model
#     ignored") -> never-integrated garbage states that crashed the swing-capture writer
#     (forrtl-66) at the first disturbance. With False the power flow matches the GUI, but that
#     dynamics crash may return. Use False to A/B the power flow; True for production runs.
APPLY_REMOVE_MACHINES = True
REMOVE_MACHINES = [
    (652549, "7"), (652549, "8"),   # COMPCC pair, one unit OOS -> model ignored
    # Machines whose USER-MODEL DLL IS MISSING ("... NOT ACCESSIBLE" in the strt log)
    # -- same pathology: no functioning model => never-integrated garbage states that
    # blow up the table writer the moment any disturbance perturbs the network:
    (910114, "1"), (910314, "1"), (910414, "1"),   # SGT8HMU1 not accessible
    (520519, "1"), (521147, "1"),                  # WT12A1U_B not accessible (BCI/BUFFBR WTG)
]

# ---- faults ---------------------------------------------------------------
FAULTS = [
     {"id": "F2_POI_SLG",  "fault_bus": POI_BUS, "type": "SLG", "cycles": 9, "trip_lines": []},
    {"id": "F3_POI_3PH",    "fault_bus": POI_BUS, "type": "3PH", "cycles": 9, "trip_lines": []},
    # {"id":"F400","fault_bus":"HENESEY4","kv":138.0,"type":"3PH","cycles":5,
    #  "pre_outage":[("BRECKNR4","NE ENID 4",138.0)],
    #  "trip_lines":[("HENESEY4","DOVERSW4",138.0)]},
]
# ---- RUN THE SAME FAULTS ON A DIFFERENT CASE -------------------------------
# Point this at an SPP_FAULTS.csv written by an earlier study and set
# AUTO_SPP_FAULTS = False, and this run executes THAT fault list verbatim
# instead of deriving one from the topology:
#
#     FAULTS_CSV      = r"C:\ENGIE\PQ23\results\EastFork_spp\faults\SPP_FAULTS.csv"
#     AUTO_SPP_FAULTS = False
#     REGEN_FAULTS    = "never"     (in the LAUNCHER -- nothing overwrites it)
#
# That is what makes two cases comparable. Left on AUTO_SPP_FAULTS, the generator
# walks the NEW case's topology, so a changed line or an added bus silently gives
# you a different fault set and F27 in one study is not F27 in the other.
#
# NOTE that SPP_FAULT_HOPS, SPP_FAULT_KV_MIN and the PLANNING_EVENTS switches
# below are inputs to the GENERATOR. With AUTO_SPP_FAULTS = False they do
# nothing -- the file decides. Changing them and expecting a different
# comparison run is the mistake this note exists to prevent.
#
# It is read only when AUTO_SPP_FAULTS is False and FAULT_MODE is "spp" -- custom
# and manual have their own sources.
# >>> ONE FAULT LIST, SHARED BY BOTH STUDIES. <<<
# The base study and the project study MUST run identical events or the
# comparison between them means nothing -- F27 in one would not be F27 in the
# other. Both scripts point at this single file, which lives outside both study
# folders precisely so neither can regenerate or delete it.
#
# It previously pointed into the OTHER study's results folder, and the other
# study pointed back into this one: circular, and each would have been reading a
# list the other's generator had produced from a DIFFERENT case.
#
# To create it: run either study once with AUTO_SPP_FAULTS = True, then copy
#   results\<project>_spp\faults\SPP_FAULTS.csv  ->  C:\ENGIE\SPP_FAULTS.csv
# and set AUTO_SPP_FAULTS = False in both. After that neither study ever
# regenerates it, so the two remain comparable however many times you re-run.
# {project} IS REPLACED WITH RUN_PROJECT. One shared list per project, because
# a fault list is built around ONE POI: SantaFe's F27 and a second project's F27
# are different events at different buses, and a single shared file would have
# every project running the first one's list under its own name. Nothing about
# the run would look wrong.
#
# Both cases still read the IDENTICAL file for a given project, which is the
# reason the shared list exists at all.
# {root} IS THE FOLDER THE CASES SIT IN -- the parent of STUDY_DIR. The shared
# fault list and SPP's own files belong beside the cases, not inside one of them:
# both cases read them, and a file inside one case folder would be moved or
# retired with that case's results.
#
# Written as a placeholder rather than computed so z4_cmp_all_con.py can still READ
# this setting out of the file with a regex -- it checks that both studies point
# at the same list before anything is simulated, and a path it cannot see is a
# check that cannot run.
def _parent_dir(p):
    """The folder one level up, without os.path.

       os.path.dirname(os.path.abspath(...)) is wrong the moment the path and
       the platform disagree: a Windows path handed to a POSIX interpreter is
       not absolute, so abspath() prepends the working directory and the parent
       comes back as the wrong folder entirely. Splitting on the separator says
       the same thing on both."""
    p = str(p).rstrip("\\/")
    i = max(p.rfind("\\"), p.rfind("/"))
    return p[:i] if i > 0 else p


CASE_ROOT = _parent_dir(STUDY_DIR)


def _with_root(path):
    return str(path).replace("{root}", CASE_ROOT)


FAULTS_CSV = r"{root}\SPP_FAULTS_CON_{project}.csv"
# Kept on ONE line above, literal and quoted, because z4_cmp_all_con.py reads this
# setting out of the file with a regex to check that both studies point at the
# same list. A path it cannot see is a check that cannot run.
FAULTS_CSV = _with_root(
    (os.environ.get("SPP_FAULTS_CSV") or FAULTS_CSV).replace(
        "{project}", RUN_PROJECT or ""))

# >>> SPP's OWN CONTINGENCY FILE (.con) AS THE FAULT LIST
# A .con is the list SPP actually studies, written from their breaker-level
# model, so it answers the one question a bus/branch case cannot: WHICH ELEMENTS
# SHARE A BREAKER. con2022_DIS2201.con carries, for POI 765911, ten events named
# "POI 765911_0" .. "_9" -- every pair of the five elements at the bus -- plus
# the P1 line and transformer events and the generator outages for the project
# itself. Generated events are an assumption; these are the study.
#
# Set FAULTS_CON to the file and FAULT_MODE to "con" (or SPP_FAULT_MODE=con from
# the launcher). Everything downstream is unchanged: the same SPP_FAULTS.csv is
# written, both cases read it, and the comparison verifies they ran the same set.
#
# ONLY WHAT IS NEAR THE POI IS IMPORTED. A .con for the whole footprint is
# 17,000 contingencies; the radius below is the same one the generated list uses,
# so a .con set and a generated set are scoped identically.
FAULTS_CON  = r"{root}\con2022_DIS2201.con"
CON_NEAR_BY = "fault_bus"   # "fault_bus" = the faulted bus is within the event's
                            #   hop limit (SPP_EVENT_HOPS), same rule as the
                            #   generated list
                            # "any_element" = keep it if ANY tripped element
                            #   touches a bus inside the radius. Wider: catches a
                            #   remote event that still trips something next to
                            #   the plant.
CON_EVENTS  = []            # [] = every event the parser understands.
                            # e.g. ["P1.2", "P4.2"] to take only those.
CON_MAX_ELEMENTS = 0        # skip a contingency removing more than N elements
                            # (0 = no cap). A 40-element P5 is a system study,
                            # not a plant study.

# >>> SPP's CLUSTER FAULT TABLE (.xlsx / .csv) AS THE FAULT LIST
# The table SPP issues with a cluster study -- Group | Event ID | Event
# Description | Event Category -- is the most complete statement of an event
# there is. Unlike a .con it says WHERE the fault goes, HOW LONG it stays on and
# WHETHER the line recloses into it:
#
#   3 Phase fault on G21-068-TAP (765911) 345 kV Bus
#     a. Apply fault at the G21-068-TAP (765911) 345 kV Bus
#     b. Clear fault after 6 cycles and trip the faulted elements:
#        b.1. G21-068-TAP (765911) 345 kV to SPERVIL7 (531469) 345 kV Transmission Circuit #1
#     c. Wait 20 cycles, and then reclose the faulted elements in (b) back into the Fault
#     d. Leave Fault on for 6 cycles, then trip the faulted elements in (b) and clear the fault
#
# Every number the simulation needs is in those five lines, so nothing about the
# event is assumed -- which is the whole difficulty with generating P4 from a
# bus/branch case, and it disappears here.
#
# Set FAULTS_TABLE and FAULT_MODE = "table" (or SPP_FAULT_MODE=table). .xlsx is
# read directly -- it is a zip of XML and both are in the standard library, so
# nothing has to be installed into PSS/E's Python. A .csv of the same four
# columns works too.
FAULTS_TABLE = r"{root}\SPP_GROPU3_FAULTS.xlsx"
TABLE_GROUPS = []           # [] = every Group in the file. e.g. ["03 CENTRAL"]
TABLE_NEAR_BY = "fault_bus" # "fault_bus" | "any_element" -- as CON_NEAR_BY

# Import SPP's file ONCE and share the result, rather than importing separately
# in every process and in both cases. See _imported_or_shared().
PREFER_SHARED_LIST = True




# ============================================================================
# >>> AUTO SPP FAULT GENERATION  (merged from make_spp_faults.py) <<<
# When AUTO_SPP_FAULTS=True the script builds the SPP BP-7250 sec.4.3.2.1 /
# TPL-001-5 fault set from the case topology around POI_BUS (instead of the manual
# FAULTS list / FAULTS_CSV), writes the Table 6-2 definitions + radius reports, then
# RUNS and PLOTS every generated fault. (RUN_FAULTS is set True above so they run.)
# NOTE: P1.1/P2.1 are NO-FAULT switching events (type "OPEN") which fault_run treats
#       as 3PH -- leave them False unless you add no-fault handling.
# ============================================================================
# ===========================================================================
# >>> WHICH FAULT SET TO RUN -- SPP OR YOUR OWN. THEY ARE EXCLUSIVE.
# ---------------------------------------------------------------------------
#   "spp"     the SPP BP-7250 set generated from the topology around the POI
#             (what AUTO_SPP_FAULTS has always done)
#   "custom"  3PH and/or SLG at every bus within CUSTOM_HOPS of the POI, held
#             for each of CUSTOM_CYCLES, with no line tripping
#   "manual"  exactly the FAULTS list written above and nothing else
#
# The launcher overrides this per run via SPP_FAULT_MODE, so one pass can do
# the SPP set and the next your own without editing anything.
#
# Custom ids look like  C01_3PH_560080_6cy  -- they cannot be confused with the
# SPP set's F01, and the results land in their own folder either way.
# ===========================================================================
FAULT_MODE = (os.environ.get("SPP_FAULT_MODE") or "spp").strip().lower()

#
# ---------------------------------------------------------------------------
# SETTINGS FOR "every project, 3-bus radius, 3PH and SLG, scored against the
# SPP criteria". The scenario count is the thing to watch, because it is a
# product and it grows fast:
#
#     scenarios per project = buses x len(CUSTOM_TYPES) x len(CUSTOM_CYCLES)
#
# with `buses` = however many are within CUSTOM_HOPS at or above CUSTOM_KV_MIN,
# then TRIMMED to CUSTOM_MAX_BUSES (nearest kept, furthest dropped).
#
#     buses  types  cycles     per project    x4 projects   per worker (6)
#      25      2      [9]           50            200            33
#      40      2      [9]           80            320            53
#      40      2      [6, 9]       160            640           107
#
# CUSTOM_MAX_BUSES = 40 with a single clearing time is the recommended run:
# 3 hops off a transmission POI typically qualifies 30-45 buses at 100 kV+, so
# 40 covers the radius without the cap quietly discarding most of it -- and the
# generator PRINTS how many it dropped, so the log tells you if 40 was short.
#
# ONE clearing time, not two. A second value doubles the whole study for a
# result that is nearly always the same shape as the first; run [9] now, and add
# [6] later for the specific faults that turn out to be marginal.
# ---------------------------------------------------------------------------
CUSTOM_HOPS      = 1              # how far from the POI to place faults
CUSTOM_KV_MIN    = 100.0          # only at or above this bus base kV
CUSTOM_TYPES     = ["3PH", "SLG"] # one scenario per type ...
CUSTOM_CYCLES    = [9]            # ... per clearing time, per bus
CUSTOM_MAX_BUSES = 40             # cap, so a dense POI cannot produce hundreds
CUSTOM_INCLUDE_POI = True         # fault the POI bus itself as well

AUTO_SPP_FAULTS    = False     # True -> generate SPP fault set from topology and run+plot it


# >>> OVERRIDABLE FROM THE ENVIRONMENT, so z4_cmp_all_con.py can generate the
# shared fault list once by running this script's BUILD role with the generator
# turned on -- without editing this file and forgetting to put it back.
#     set SPP_AUTO_FAULTS=1
_enva = (os.environ.get("SPP_AUTO_FAULTS") or "").strip().lower()
if _enva in ("1", "true", "yes", "on"):
    AUTO_SPP_FAULTS = True
    print("[faults] AUTO_SPP_FAULTS forced ON from the environment -- this run "
          "GENERATES the fault set from this case's topology")
elif _enva in ("0", "false", "no", "off"):
    AUTO_SPP_FAULTS = False
SPP_FAULT_HOPS     = 2        # POI + this many bus-hops of elements to fault
SPP_FAULT_KV_MIN   = 100.0    # only fault elements at/above this kV

# ---- HOW FAR OUT, PER EVENT TYPE -------------------------------------------
# The SPP Generator Interconnection Manual does NOT use one radius for
# everything:
#
#   "Fault events will include P1 events involving each network circuit segment
#    connected within THREE levels of each Current-Study Request's POI as well as
#    P4 and P6 events involving each network circuit connected within TWO levels
#    of each Current-Study Request's POI."
#
# One SPP_FAULT_HOPS for every event cannot express that. Set to 3 it over-runs
# P4/P6 by a level; set to 2 it under-runs P1 by a level -- and under-running is
# a study that does not meet the manual, with nothing in the output to say so.
#
# An event not listed here uses SPP_FAULT_HOPS. Set a value to None to use
# SPP_FAULT_HOPS explicitly.
SPP_EVENT_HOPS = {
    "P1.1": 4,      # generator loss           -- P1
    "P1.2": 4,      # 3ph line fault           -- P1
    "P1.3": 4,      # 3ph transformer fault    -- P1
    "P2.1": 4,      # line section opened      -- P2
    "P4.2": 2,      # SLG stuck breaker        -- P4
    "P6":   2,      # prior-outage 3ph         -- P6
    "P7":   2,      # common tower             -- P7 (as necessary)
}


def sf_event_hops(ev):
    """Levels out from the POI for one planning event."""
    h = SPP_EVENT_HOPS.get(ev, None)
    return SPP_FAULT_HOPS if h is None else int(h)

SPP_STUCK_CYCLES   = 16       # stuck-breaker total clearing (cycles) -- SPP's own
                              # reports use 16. Kept as the fallback for anything
                              # that does not go through SPP_EVENT_CYCLES.

# ---- CLEARING TIME, PER PLANNING EVENT --------------------------------------
# SPP does not use one clearing time either. Their reports show 6 cycles at
# 345 kV and 7 below for a normally-cleared 3-phase fault, and 16 for a
# single-phase fault with a stuck breaker -- different protection, different
# time, in the same study.
#
# Each entry is one of:
#   None          use SPP_CLEAR_BY_KV (or NORMAL_CLEAR_CYCLES if that is set)
#   a number      that many cycles, at every kV
#   [(kv, cyc)]   a kV table of its own, highest kV first
#
# An event not listed here falls back to SPP_CLEAR_BY_KV. Anything set here is
# what goes into the fault list AND into the SPP contingency text, so the
# description and the simulation cannot disagree.
SPP_EVENT_CYCLES = {
    "P1.2": None,                    # 3ph line       -- 6 at >=300 kV, 7 below
    "P1.3": None,                    # 3ph transformer
    "P2.1": 0,                       # switching only, no fault
    "P4.2": [(300.0, 16), (0.0, 16)],  # stuck breaker -- SPP's reports show 16
    "P6":   None,                    # prior-outage 3ph
    "P7":   None,                    # common tower
}


def sf_event_cycles(ev, kv):
    """Clearing cycles for one planning event at one kV."""
    spec = SPP_EVENT_CYCLES.get(ev, None)
    if spec is None:
        return sf_clear_cycles(kv)
    if isinstance(spec, (list, tuple)):
        for thr, c in spec:
            if kv >= thr:
                return c
        return sf_clear_cycles(kv)
    return spec

SPP_SLG_RETAIN_VPU = 0.60     # SLG held to 0.6 pu (SPP approximation)
SPP_MAX_FAULTS     = 200    # cap on generated faults -- high value = run ALL faults in the POI radius
                            # (was 5, which cut generation off at 5 P1.2 line faults before P1.3/P4.2/P6
                            #  were ever added). Each fault is a full ~20 s sim + SLG autotune, so ALL
                            #  faults can be a long run -- narrow it with SPP_FAULT_HOPS / SPP_FAULT_KV_MIN
                            #  if the generated count (printed as "built N fault(s)") is more than you want.
# >>> FAULT BOTH ENDS OF EVERY LINE -----------------------------------------
# A line fault can be applied at either terminal, and the two are completely
# different tests: the near-end fault is the severe one for the equipment at that
# bus. The generator used to take only the terminal the case stores as "from",
# which for your intertie is 587310 -- so the POI-end fault at 560080 (the one the
# SPP table calls F01) was never created. With this True, P1.2 and P4.2 create a
# fault at BOTH terminals; the POI-outward sort then places the POI-end one first.
# Costs roughly 2x the generated P1.2/P4.2 count -- SPP_MAX_FAULTS still keeps only
# the N nearest the POI, so raise it if you want the far-out faults back.
SPP_FAULT_BOTH_ENDS  = False

ENABLE_RECLOSE       = True   # emit the c./d. reclose steps for P1.2 & P6 (in the definitions)
RECLOSE_WAIT_CYCLES  = 20     # 'c. Wait N cycles, then reclose ...'
# >>> SPP, 2026-08: "if reclosing would cause islanding of a generator, it is
#     removed from the contingency". True applies that at generation time: a
#     reclose whose tripped elements leave a machine with no other path is not
#     emitted, and every one suppressed is listed. False = emit it regardless,
#     which is what this did before the rule was known.
RECLOSE_SKIP_IF_ISLANDS = True
# >>> SIMULATE_RECLOSE: actually PERFORM the Appendix-D unsuccessful reclose in the simulation
#     (not just describe it in the report). For faults with reclose=True (P1.2 line, P6 prior-outage):
#     after clearing+tripping (b), wait RECLOSE_WAIT_CYCLES, dist_branch_close the tripped element
#     back INTO a re-applied fault (c), hold for the clear-cycles, then trip+clear permanently (d).
#     The plot then shows the real SECOND voltage dip. False = old behaviour (apply+clear+trip only).
SIMULATE_RECLOSE     = True 
SPP_EVENTS = {
    "P1.1": False,   # generator loss (no fault) -- not required by the BPM paragraph
    "P1.2": True,    # 3ph LINE fault + unsuccessful reclose        -- P1
    "P1.3": True,    # 3ph TRANSFORMER fault (no reclose, per BPM)  -- P1
    "P2.1": False,    # LINE section opened, no fault                -- P2.1-2.3
    "P4.2": True,    # SLG stuck-breaker fault + backup clearing    -- P4
    "P6":   False,    # 3ph on a PRIOR-OUTAGE case (N-1-1) + reclose -- P6
                     #
                     # P6 IS THE EXPENSIVE ONE. It is the only event needing its
                     # own .cnv/.snp per fault, because the prior outage has to be
                     # solved into the base case before the fault is applied. That
                     # is more build time per scenario and more files on disk. The
                     # snapshot names are now per-worker, so parallel workers no
                     # longer collide on them (see build_case/fault_run) -- that
                     # collision was the [Errno 13] Permission denied.
                     # P6_MAX_PER_BUS caps the (pre-outage, fault) pairs per bus.
    "P7":   False,   # common-tower / double-circuit 3ph -- "as necessary" in the
                     # BPM; turn on when SPP asks for it.
}
# >>> P4 STUCK BREAKER -- HOW MANY ELEMENTS THE FAILED BREAKER TAKES
# TPL-001-4 Table 1 P4 is a fault PLUS A STUCK BREAKER, and what is lost is what
# the BREAKER FAILURE BACKUP PROTECTION clears -- decided by the station's
# breaker configuration. SPP's own P4 lists show that plainly: at KILDEER7
# (652419) each stuck-breaker event trips ONE circuit, at BELFELD3 (652424) the
# events trip two to four elements each, and there are several events per bus --
# one per breaker, not one per bus.
#
# A PSS/E raw case has NO BREAKERS IN IT. It has buses and branches, so which
# elements share a breaker cannot be derived, only assumed:
#
#   2   EVERY PAIR of elements at the bus -- one event per pair. THE DEFAULT,
#       because it is what SPP's own generator does at this POI: their .con
#       carries "POI 765911_0" .. "_9", which is all ten pairs of the five
#       elements on 765911, and their cluster table's P4 events at the POI trip
#       two elements each. A ring bus or breaker-and-a-half station loses the
#       two elements either side of the failed breaker, and which two depends on
#       a layout the case does not contain -- so every pair is tested.
#   1   one event per element, tripping that element. The least severe reading,
#       and what SPP writes at simple stations like KILDEER7 (652419).
#   0   every element at the bus in one event. The most severe: right for a
#       single-bus station (WILISTN7 shape), but at a radial tap it disconnects
#       the plant outright and every criterion then measures the loss of the
#       plant instead of the system's response to a fault.
#   3+  every combination of that many elements. The count grows fast: a
#       6-element bus gives 20 events at 3, 15 at 2.
#  -1   ALL BUT ONE. A bus with 4 elements gives 4 events of 3 elements, 5
#       gives 5 events of 4, 3 gives 3 events of 2 -- every combination of that
#       size, so each event leaves a different element in service. This is the
#       double-bus reading: a bus fault with a stuck breaker loses everything on
#       the faulted bus section except what the surviving breaker holds. SPP's
#       WILISTN7 event is this shape. -2 leaves two in, and so on.
# "all" EVERY COMBINATION OF EVERY SIZE, from one element up to all but one.
#       Nothing about the station is assumed at all, at the price of 2^N - 2
#       events per bus: 14 at a 4-element bus, 62 at 6. The count is printed
#       per bus so it cannot surprise you at the end of a build.
#
# Whichever is chosen is written into the contingency description, because the
# station configuration is an ASSUMPTION and the reader has to see it to agree
# with the event. WITH SPP's OWN LIST (FAULT_MODE "con" or "table") none of this
# applies: the groups come from their breaker model and nothing is assumed.
SPP_P4_GROUP        = -1
# >>> HOW THE P4 ELEMENT SET IS CHOSEN -- SPP'S OWN ANSWER, 2026-08.
#
#   "Disconnected elements for P4 stuck-breaker contingencies are primarily
#    extracted from the P4 steady-state contingency definitions provided in the
#    corresponding ITP auxiliary files, using an assumed 16-cycle clearing time.
#    TO-submitted stability fault sheets are also leveraged for additional P4
#    definitions... For busbars missing P4 contingency definitions, or where
#    definitions are found to be altered by the interconnection of new
#    generation, SPP defines two proxy P4 events: (a) outage of the entire
#    busbar, and (b) outage of the two highest-loaded branches."
#
# We hold neither the ITP auxiliary files nor the TO fault sheets, so every bus
# here is a "busbar missing a P4 contingency definition" and SPP's own proxy is
# the definition to use. That is what "spp-proxy" builds, and it is the default:
#
#   "spp-proxy"  per busbar, exactly two events --
#                  a) the ENTIRE busbar out
#                  b) the TWO HIGHEST-LOADED branches at it, by MVA in the
#                     solved case
#   "group"      the old behaviour: SPP_P4_GROUP combinations of the elements
#                at the bus. Useful for a deliberately wider sweep; it is NOT
#                what SPP describes.
#
# WHERE AN ITP OR TO DEFINITION IS IN HAND, it beats both -- put it in
# FAULTS_CSV and set FAULT_MODE = "table", which bypasses this generator.
SPP_P4_MODE         = "spp-proxy"
# A physically single line modelled as several segments through tap buses goes
# out in ALL its segments when its breaker opens -- SPP's LELAND_O-BE3 event
# trips LELAND->LO.LS-GR, LO.LS-GR->GR.LS-LO and GROTON->GR.LS-LO as one thing.
# A tap bus here is a bus with exactly two lines and no machine and no load.
SPP_P4_TAP_SEGMENTS = True

P6_MAX_PER_BUS      = 6                      # cap on (pre-outage, fault) pairs per bus
NORMAL_CLEAR_CYCLES = None                # None -> use SPP_CLEAR_BY_KV; a number -> uniform
# ---- what z4_cmp_all_con.py sends (see _env_str/_env_num above) --------------------
# Applied HERE, after every one of these settings has been given its value in
# this file, so the override is the last word and there is one place to look
# when a run does not do what the file says.
FAULTS_CON          = _with_root(_env_str("SPP_FAULTS_CON", FAULTS_CON))
FAULTS_TABLE        = _with_root(_env_str("SPP_FAULTS_TABLE", FAULTS_TABLE))
CON_NEAR_BY         = _env_str("SPP_CON_NEAR_BY", CON_NEAR_BY)
TABLE_NEAR_BY       = _env_str("SPP_CON_NEAR_BY", TABLE_NEAR_BY)
CON_EVENTS          = _env_list("SPP_CON_EVENTS", CON_EVENTS)
TABLE_GROUPS        = _env_list("SPP_TABLE_GROUPS", TABLE_GROUPS)
CON_MAX_ELEMENTS    = int(_env_num("SPP_CON_MAX_ELEMENTS", CON_MAX_ELEMENTS))
SPP_FAULT_HOPS      = int(_env_num("SPP_FAULT_HOPS", SPP_FAULT_HOPS))
# ---- the rest of what z4_cmp_all_con.py owns -----------------------------------
AUTO_SPP_FAULTS     = _env_bool("SPP_AUTO_FAULTS", AUTO_SPP_FAULTS)
CUSTOM_HOPS         = int(_env_num("SPP_CUSTOM_HOPS", CUSTOM_HOPS))
RUN_NPLT            = max(1, int(_env_num("SPP_RUN_NPLT", RUN_NPLT)))
CUSTOM_KV_MIN       = float(_env_num("SPP_CUSTOM_KV_MIN", CUSTOM_KV_MIN))
CUSTOM_MAX_BUSES    = int(_env_num("SPP_CUSTOM_MAX_BUSES", CUSTOM_MAX_BUSES))
CUSTOM_INCLUDE_POI  = _env_bool("SPP_CUSTOM_INCLUDE_POI", CUSTOM_INCLUDE_POI)
CUSTOM_TYPES        = [str(x).upper() for x in _env_list("SPP_CUSTOM_TYPES", CUSTOM_TYPES)]
# A TABLE BY TYPE, OR A LIST. z4_cmp_all_con.py sends {"3PH": null, "SLG": 16} as
# JSON when CUSTOM_CYCLES is a dict there, so the clearing time can follow the
# fault type -- SPP's kV rule for a three-phase fault, 16 cycles for the SLG
# stuck-breaker case. A bare list is the older form and still means "these
# clearing times, for every type".
_ccr = (os.environ.get("SPP_CUSTOM_CYCLES") or "").strip()
if _ccr.startswith("{"):
    try:
        import json as _json_cc
        CUSTOM_CYCLES = _json_cc.loads(_ccr)
    except Exception as _e:
        print("[faults] SPP_CUSTOM_CYCLES is not readable JSON (%s) -- keeping %s"
              % (_e, CUSTOM_CYCLES))
else:
    _cc = _env_list("SPP_CUSTOM_CYCLES", None)
    if _cc:
        try:
            CUSTOM_CYCLES = [float(x) if "." in x else int(x) for x in _cc]
        except ValueError:
            print("[faults] SPP_CUSTOM_CYCLES is not a list of numbers -- keeping %s"
                  % CUSTOM_CYCLES)
RUN_FLAT            = _env_bool("SPP_RUN_FLAT", RUN_FLAT)
RUN_FAULTS          = _env_bool("SPP_RUN_FAULTS", RUN_FAULTS)
MAKE_PLOTS          = _env_bool("SPP_MAKE_PLOTS", MAKE_PLOTS)
FORCE_REBUILD       = _env_bool("SPP_FORCE_REBUILD", FORCE_REBUILD)
MAX_SCENARIO_ATTEMPTS = int(_env_num("SPP_MAX_ATTEMPTS", MAX_SCENARIO_ATTEMPTS))
POI_RADIUS_HOPS     = int(_env_num("SPP_POI_RADIUS_HOPS", POI_RADIUS_HOPS))
# ---- WHAT IS RECORDED, FROM THE PANEL --------------------------------------
# These two decide the SIZE OF EVERY .out, and they were reachable only by
# editing this file and its twin and keeping the two in step. The note beside
# PLOT_MAX_PANELS already says they are the lever that matters:
#
#   "Plot time is set by how many channels were RECORDED, not by how many are
#    drawn. Recording fewer -- a higher AREA_KV_MIN, a shorter STUDY_AREAS --
#    makes the .out smaller, the plots faster and the memory survivable."
#
# 21 areas at 100 kV is ~7,900 channels, which is a 111 MB .out per scenario and
# 29.1 million Python floats to read one -- past what a 32-bit reader can do
# without paging. Nothing downstream can undo that, so it belongs where the rest
# of the study's decisions are.
_sa = (os.environ.get("SPP_STUDY_AREAS") or "").strip()
if _sa:
    try:
        _sal = [int(x) for x in re.split(r"[,\s]+", _sa) if x.strip()]
        if _sal:
            print("[mon] STUDY_AREAS from z4_cmp_all_con.py: %d area(s) -> %s"
                  % (len(_sal), ", ".join(str(x) for x in _sal)))
            STUDY_AREAS = _sal
    except Exception:
        print("[mon] SPP_STUDY_AREAS is not a list of area numbers (%r) -- "
              "keeping this file's %d area(s)" % (_sa, len(STUDY_AREAS)))
AREA_KV_MIN = float(_env_num("SPP_AREA_KV_MIN", AREA_KV_MIN))
# PER-EVENT HOPS, as a table. Only the events named are changed, so a partial
# override leaves the rest of the study's own table alone.
_evh = (os.environ.get("SPP_EVENT_HOPS") or "").strip()
if _evh:
    try:
        import json as _json
        for _k, _v in _json.loads(_evh).items():
            SPP_EVENT_HOPS[str(_k)] = int(_v)
        print("[faults] event hops from z4_cmp_all_con.py: %s"
              % ", ".join("%s=%d" % (k, SPP_EVENT_HOPS[k]) for k in sorted(SPP_EVENT_HOPS)))
    except Exception as _e:
        print("[faults] SPP_EVENT_HOPS could not be read (%s) -- using this file's table"
              % _e)
SPP_FAULT_KV_MIN    = float(_env_num("SPP_FAULT_KV_MIN", SPP_FAULT_KV_MIN))
SPP_MAX_FAULTS      = int(_env_num("SPP_MAX_FAULTS", SPP_MAX_FAULTS))
SPP_P4_TAP_SEGMENTS = _env_bool("SPP_P4_TAP_SEGMENTS", SPP_P4_TAP_SEGMENTS)
SPP_P4_MODE         = (os.environ.get("SPP_P4_MODE") or SPP_P4_MODE).strip()
# THE THREE RECLOSE SWITCHES, from z4_cmp_all_con.py. ENABLE_RECLOSE decides whether
# the step is described at all, SIMULATE_RECLOSE whether it is actually performed,
# and RECLOSE_SKIP_IF_ISLANDS applies SPP's "removed if it would island a
# generator" rule. Read here beside the other fault settings so one panel governs
# the fault set on both cases.
ENABLE_RECLOSE      = _env_bool("SPP_ENABLE_RECLOSE", ENABLE_RECLOSE)
SIMULATE_RECLOSE    = _env_bool("SPP_SIMULATE_RECLOSE", SIMULATE_RECLOSE)
RECLOSE_SKIP_IF_ISLANDS = _env_bool("SPP_RECLOSE_SKIP_ISLANDS",
                                    RECLOSE_SKIP_IF_ISLANDS)
SPP_STUCK_CYCLES    = int(_env_num("SPP_STUCK_CYCLES", SPP_STUCK_CYCLES))
RECLOSE_WAIT_CYCLES = int(_env_num("SPP_RECLOSE_WAIT", RECLOSE_WAIT_CYCLES))
SPP_SLG_RETAIN_VPU  = float(_env_num("SPP_SLG_RETAIN", SPP_SLG_RETAIN_VPU))
# "all" is a word, every other value a number -- kept as whichever it is, since
# p4_groups() reads both.
_p4g = (os.environ.get("SPP_P4_GROUP") or "").strip()
if _p4g:
    SPP_P4_GROUP = _p4g if _p4g.lower() == "all" else int(float(_p4g))
_ncc = (os.environ.get("SPP_NORMAL_CLEAR_CYCLES") or "").strip()
if _ncc:
    NORMAL_CLEAR_CYCLES = int(float(_ncc))
# Which planning events to build. Sent as a list of names; anything not named
# is turned OFF, so the setting says what the study runs rather than adding to
# whatever was already on.

# ---- COLLECTOR IMPEDANCE FROM z4_cmp_all_con.py ----------------------------------
# Sent as JSON so a table survives the trip through the environment intact. Not
# set -> the table written in this file stands, and a standalone run behaves
# exactly as it reads.
_collj = (os.environ.get("SPP_COLL_BRANCHES") or "").strip()
if _collj:
    try:
        import json as _json
        COLLECTOR_BRANCHES = dict((k, [tuple(r) for r in v])
                                  for k, v in _json.loads(_collj).items())
    except Exception as _e:
        print("[coll] SPP_COLL_BRANCHES could not be read (%s) -- using this "
              "file's table" % _e)
_collsj = (os.environ.get("SPP_COLL_SCALE") or "").strip()
if _collsj:
    try:
        import json as _json
        COLLECTOR_SCALE = dict((k, tuple(v)) for k, v in _json.loads(_collsj).items())
    except Exception as _e:
        print("[coll] SPP_COLL_SCALE could not be read (%s) -- ignored" % _e)
COLLECTOR_ON = _env_bool("SPP_COLL_ON", COLLECTOR_ON)
_collb = (os.environ.get("SPP_COLL_BASE_MVA") or "").strip()
if _collb:
    try:
        COLLECTOR_Z_BASE_MVA = float(_collb)
    except ValueError:
        pass


_evon = _env_list("SPP_EVENTS_ON", None)
if _evon:
    SPP_EVENTS = dict((k, (k in _evon)) for k in SPP_EVENTS)
    print("[faults] planning events from z4_cmp_all_con.py: %s"
          % ", ".join(sorted(k for k, v in SPP_EVENTS.items() if v)))

                                           # None because SPP_CLEAR_BY_KV IS the table SPP's
                                           # reports use: 6 cycles at >=300 kV, 7 below. A
                                           # number here overrides it for every kV, which is
                                           # how every fault came out at 10.
SPP_CLEAR_BY_KV     = [(345.0, 6), (0.0, 7)] # normal-clear cycles by kV
# >>> SPP'S OWN ANSWER, 2026-08: "Clearing time is assumed to be 6 cycles for
#     345 kV and above, and 7 cycles for 230 kV and below." The threshold was
#     300, which gives the same answer on this system (there is no bus between
#     230 and 345 kV) but does not say what SPP said. It says it now.
#
#     SPP add that where an issue is seen they confirm the time with the host
#     TO and use the TO-submitted fault-clearing time, which "may be lower than
#     the assumed values above" -- so these are the assumption to study with,
#     not the number a mitigation discussion would end on.


# ---- SPP CRITERIA (Rev 3.0) ----------------------------------------------
V_RECOVERY_PU  = 0.70
V_RECOVERY_S   = 2.5
V_OVERSHOOT_PU = 1.20
# >>> "...UNLESS AFFECTED TRANSMISSION SYSTEM ELEMENTS ARE DESIGNED TO HANDLE
#      THE RISE ABOVE 1.2 PER UNIT" -----------------------------------------
#
# Rev 3.0 allows exactly one exception to the 1.20 pu limit, and it is about
# EQUIPMENT: a bus whose affected elements are designed for the rise. Nothing
# else in the requirement is discretionary.
#
# So it is a table of buses with the REASON that makes each one exempt, and the
# reason is not optional -- an exemption with no justification is a threshold
# quietly raised, and it would be raised in the one file a reviewer reads to
# see whether the threshold was met. Every exempt bus is named in the criterion
# line and in the violations report, with its reason and the limit applied, so
# the exception is visible wherever the result is.
#
#   V_OVERSHOOT_EXEMPT = {
#       761376: "35 kV collector, insulated for 1.3 pu -- OEM datasheet DS-1183",
#       761383: (1.25, "POI 345 kV, TO confirmed 1.25 pu withstand, email 2026-07-14"),
#   }
#
# A bare string exempts the bus from the 1.20 limit entirely (it is still
# recorded and reported). A (limit, reason) pair judges it against that limit
# instead -- which is the more defensible form, and the one to prefer.
V_OVERSHOOT_EXEMPT = {}
V_SS_LOW, V_SS_HIGH = 0.90, 1.10
SS_WINDOW_S    = 1.0
ANGLE_DEV_DEG  = 16.0
# ---- the limits, when z4_cmp_all_con.py sets them ------------------------------
# Applied here, below the definitions. These decide PASS and FAIL, so they must
# be identical in both cases -- two studies scored against different thresholds
# produce a comparison whose differences ARE the thresholds, and nothing in the
# report would say so.
V_RECOVERY_PU  = float(_env_num("SPP_V_RECOVERY_PU", V_RECOVERY_PU))
V_RECOVERY_S   = float(_env_num("SPP_V_RECOVERY_S", V_RECOVERY_S))
V_OVERSHOOT_PU = float(_env_num("SPP_V_OVERSHOOT_PU", V_OVERSHOOT_PU))
V_SS_LOW       = float(_env_num("SPP_V_SS_LOW", V_SS_LOW))
V_SS_HIGH      = float(_env_num("SPP_V_SS_HIGH", V_SS_HIGH))
ANGLE_DEV_DEG  = float(_env_num("SPP_ANGLE_DEV_DEG", ANGLE_DEV_DEG))
SPPR1_DECAY    = 0.05
SPPR5_DECAY    = 0.226
FLAT_TOL       = 0.1
# ---- WHAT "FLAT" MEANS, PER QUANTITY --------------------------------------
# THE FLAT RUN WAS FAILING ON CHANNELS THAT WERE NOT DRIFTING.
#
# One number was applied to every monitored channel, as
#       max(v) - min(v)  >  FLAT_TOL * max(1.0, |v[0]|)
# and the channels are in different units. For a machine at 500 MW that is a
# 50 MW tolerance -- far too loose. For anything INITIALISED AT ZERO the
# max(1.0, ...) floor makes it 0.1 of whatever the unit happens to be:
#
#   * POI Mvar, which this study deliberately starts at 0 (Q_FRACTION_AT_POI)
#     -> 0.1 Mvar
#   * a rotor angle taken against a reference bus, starting near 0 degrees
#     -> 0.1 degrees
#
# Neither of those is initial-condition drift; both are the ordinary numerical
# wander of a 20-second no-fault run, and either is enough to fail the flat run
# -- which is SPP's initialisation test, and the thing every fault result rests
# on. A study whose flat run "fails" reports every fault as a failure too, and
# nothing in the report says why.
#
# So the tolerance is per quantity, in that quantity's own units, ABSOLUTE:
#
#   VOLT    pu        a bus that moves 0.01 pu with no disturbance is drifting
#   ANGLE   degrees   1 degree over 20 s with nothing happening
#   PELEC   MW        judged against the machine's own output as well, below
#   QELEC   Mvar
#   SPEED   pu        machine speed; 1e-4 pu is 0.006 Hz
#   ETERM   pu
#
# A channel also passes if it moved less than FLAT_REL of its own initial
# value, so a 500 MW machine is not held to 1 MW. Set FLAT_TOL_BY_KIND to {}
# to go back to the single-number test.
FLAT_TOL_BY_KIND = {
    "VOLT":  0.005,     # pu
    "ETERM": 0.005,     # pu
    "ANGLE": 1.0,       # degrees
    "PELEC": 1.0,       # MW
    "QELEC": 2.0,       # Mvar -- inverters idle with more wander than this
    "SPEED": 0.0002,    # pu  (0.012 Hz)
}
FLAT_REL = 0.02         # ...or 2 % of the channel's own initial value, whichever is larger
_ftk = (os.environ.get("SPP_FLAT_TOL_BY_KIND") or "").strip()
if _ftk:
    try:
        import json as _json
        FLAT_TOL_BY_KIND = dict((str(k).upper(), float(v))
                                for k, v in _json.loads(_ftk).items())
    except Exception as _e:
        print("[flat] SPP_FLAT_TOL_BY_KIND could not be read (%s) -- ignored" % _e)
FLAT_REL = float(_env_num("SPP_FLAT_REL", FLAT_REL))

# ---- WHEN the transient-overvoltage search STARTS -------------------------
# Seconds after the simulated clearing time before the search for the peak
# begins. This was hard-coded at 0.02 inside evaluate_case, and 20 ms is
# exactly where the recovery overshoot lives, so the check was blind to the
# spike it exists to catch:
#     C01_3PH_560080_9cy  POI 560080  max 1.266 pu @ 5.17 s   -> reported "OK"
#     C01_3PH_560080_9cy  PROJ 587317 max 1.193 pu @ 5.17 s
#     C01_3PH_560080_9cy  bus 515375  max 1.057 pu @ 5.17 s
# Every channel peaks at the same instant -- the sample at clearing -- because
# that is when the fault is removed. With the window opening 20 ms later, all
# of them were skipped.
#
# 0.0 = judge from the instant of clearing, which is the strict reading and the
# default. Raise it only with a documented reason; it makes the test weaker.
V_OVERSHOOT_BLANK_S = 0.0

# ---- THE SWITCHING STEP vs THE SWING (transient overvoltage) ---------------
# WHAT THE CRITERION ACTUALLY SAYS. SPP's Transient Voltage Recovery
# Requirement, and the shaded region of its Figure 3, are explicit:
#
#     Bus voltage excursions above 1.20 PU ANYTIME after the fault is cleared
#     (time = T sec) are considered unacceptable (unless affected transmission
#     system elements are designed to handle the rise above 1.2 PU.)
#
# In the figure the unacceptable region begins AT the clearing line -- there is
# no blanking window, no settling allowance, and the word is "excursions", not
# "swings". An excursion above 1.20 pu one sample after clearing is a violation.
#
# THIS DEFAULT WAS WRONG AND IS NOW CORRECTED. It shipped as True, which judged
# from 2 cycles after clearing and excused everything inside that window --
# including bus 768281 in IronStar F01, which reaches 1.283 pu at the clearing
# sample and was reported as compliant. The reasoning was that removing the
# fault admittance is a step change in a positive-sequence network and the
# sample at that instant is an algebraic jump rather than an electromechanical
# swing. That may well be true as physics, and it is still measured and
# reported -- but it is an argument to put to SPP about a violation, not a
# licence to not report one. The criterion is the criterion.
#
# V_OVERSHOOT_SWING_S    how long after clearing the swing window opens. Now a
#                        DIAGNOSTIC only: both peaks are always measured, so a
#                        reader can see whether a violation is a real swing or
#                        the switching sample, and the violation is reported
#                        either way. 2 cycles at 60 Hz.
# V_OVERSHOOT_JUDGE_SWING False = the verdict is measured from the clearing
#                        instant -- "anytime after the fault is cleared", as
#                        written. THE DEFAULT.
#                        True  = the verdict is the swing only. Weaker than the
#                        criterion as written; set it only if SPP confirms in
#                        writing that they blank the switching instant, and say
#                        so in the study report.
V_OVERSHOOT_SWING_S      = 2.0 / 60.0
V_OVERSHOOT_JUDGE_SWING  = False

# ---- what counts as a TRIPPED machine ------------------------------------
# A machine counts as tripped on POWER when it was carrying more than
# TRIP_PGEN_MIN_MW before the disturbance and ENDS BELOW TRIP_PGEN_DEAD_MW --
# an absolute level in MW, not a fraction of what it carried. The fraction test
# (TRIP_RESIDUAL_FRAC) that used to decide it is kept only as a guard, so a
# small unit that never moved (dispatched at 6 MW, still at 6 MW) is not called
# tripped: the end value must ALSO be below TRIP_RESIDUAL_FRAC of the pre-fault
# value. All three are MW on the system base (see SYS_MVA_BASE).
# RULE: a machine is TRIPPED only if its power goes to ZERO after the fault.
# TRIP_PGEN_DEAD_MW was 10.0: a 2.01 MW unit that settled at 0.78 MW (39 %,
# terminal voltage healthy, still on line) was reported "TRIPPED 2.01 -> 0.78
# MW" and became a NEW violation, while the same unit in the other case at
# 2.47 -> 1.56 MW was not. 0.05 MW is numerical zero for a channel recorded
# in pu on a 100 MVA base; a machine that is still connected never sits there.
TRIP_PGEN_MIN_MW    = 0.5      # was carrying at least this before the fault
TRIP_PGEN_DEAD_MW   = 0.05     # ...and ends at ZERO (below this, in MW) -> tripped
TRIP_RESIDUAL_FRAC  = 0.10     # ...and below this fraction of pre-fault (never binds once DEAD is 0.05; kept as a guard)
try:
    TRIP_PGEN_DEAD_MW = float(os.environ.get("SPP_TRIP_PGEN_DEAD_MW") or TRIP_PGEN_DEAD_MW)
    TRIP_RESIDUAL_FRAC = float(os.environ.get("SPP_TRIP_RESIDUAL_FRAC") or TRIP_RESIDUAL_FRAC)
except Exception:
    pass
# PELEC / QELEC channels are pu on the SYSTEM MVA base. Everything that reports
# a machine's power in MW -- the trip test, its wording, the violation rows and
# the machines table -- multiplies by this. SPP_SBASE overrides it.
SYS_MVA_BASE = 100.0
try:
    SYS_MVA_BASE = float(os.environ.get("SPP_SBASE") or SYS_MVA_BASE)
except Exception:
    pass
# >>> A TRIP THE P-BASED CHECK CANNOT SEE ------------------------------------
#
# The PELEC test above catches a machine that was CARRYING LOAD and stopped.
# Bus 584713 tripped in C01 and passed it: the unit was dispatched at ~0.03 MW
# -- below TRIP_PGEN_MIN_MW -- so "was it delivering before, and nothing now"
# had nothing to compare. Its terminal voltage told the whole story: ETERM
# 1.013 pu before the fault, 0.000 pu from clearing to the end of the run. A
# machine whose terminals are dead is off the system whatever its dispatch
# was, and the report said "459 machine(s) checked, all still generating".
#
# So a machine ALSO counts as tripped when its terminal voltage collapses:
# ETERM at least TRIP_ETERM_PREFAULT_PU before the fault and averaging below
# TRIP_ETERM_DEAD_PU over the last twentieth of the run. Both thresholds are
# deliberately far apart -- a depressed-but-alive bus sits at 0.5-0.9 pu, a
# disconnected machine at ~0 -- so this cannot fire on a voltage dip.
TRIP_ETERM_PREFAULT_PU = 0.50
TRIP_ETERM_DEAD_PU     = 0.20

# ---- the voltage criteria apply to BULK ELECTRIC SYSTEM buses only --------
# SPP Rev 3.0: "Bus voltages ON THE BULK ELECTRIC SYSTEM shall recover above
# 0.70 per unit ... shall not swing above 1.20 per unit", and the OVERVIEW says
# "These Requirements shall not be applicable to facilities that are not part of
# Bulk Electric System."
#
# The check used to judge EVERY voltage channel, which pulls in the 0.69 kV
# inverter terminals and the 34.5 kV collector of the project itself. Those are
# not BES, they swing much harder than the transmission system, and scoring them
# produces failures that are not violations of this standard.
#
# 100 kV is the BES threshold. A bus whose base kV cannot be resolved is JUDGED
# rather than skipped -- excluding an unknown would quietly narrow the test.
BES_KV_MIN = 100.0

# ---- rotor-angle peak detection ------------------------------------------
# A positive peak must rise at least this many degrees above the neighbouring
# trough to count. Pure numerical ripple on a settled trace would otherwise be
# read as a sequence of peaks and fed into the SPPR ratios.
PEAK_MIN_PROMINENCE_DEG = 0.05
# ...AND AT LEAST THIS FRACTION OF THE SWING BEING JUDGED.
#
# 0.05 deg alone is not a threshold on a 100 degree swing -- every sample of
# numerical ripple clears it, so the recovery from a fault produced TWO "positive
# peaks" a few samples apart at almost the same height:
#
#     SPPR1 = (2nd peak - min) / (1st peak - min) = 0.982   -> "undamped"
#
# on machines whose traces are visibly flat within a tenth of a second. SPP's
# Figure 2 measures successive peaks of an OSCILLATION; a shoulder on a
# monotone recovery is not one, and calling it one fails a machine that is
# settled. A peak must now stand this fraction of the judged deviation above the
# troughs either side of it as well.
PEAK_MIN_PROMINENCE_FRAC = 0.02

# >>> WHEN SPPR CANNOT BE MET NO MATTER HOW WELL DAMPED THE MACHINE IS --------
#
# SPPR measures every positive peak against the MINIMUM VALUE of the trace:
#
#     SPPR1 = (peak2 - vmin) / (peak1 - vmin)
#
# In SPP's Figure 2 the minimum is the trough of the SAME oscillation, so as the
# swing decays every peak walks down towards that minimum and the ratio falls
# towards zero. That is the case the numbers 0.95 and 0.774 were chosen for.
#
# A machine that settles WELL ABOVE its minimum does not behave that way. If the
# fault drives the angle down to -34.2 deg, the first peak comes back to
# -14.5 deg and the machine then settles at -17.6 deg, the peaks decay towards
# -17.6 and NOT towards -34.2, so the ratio decays towards
#
#     floor = (settle - vmin) / (peak1 - vmin) = (-17.6 + 34.2)/(-14.5 + 34.2) = 0.84
#
# and can never reach 0.774, let alone 0.95's worth of margin -- however
# perfectly damped the machine is. The deep minimum there is the fault excursion
# itself, not a trough of the ringing.
#
# THAT IS A PROPERTY OF THE MEASUREMENT, NOT OF THE MACHINE, and reporting it as
# "undamped" is wrong. So the floor is computed, and when
#
#   * the failing ratio is below its own floor plus a hair (nothing else was
#     achievable), and
#   * the SAME peaks measured about the SETTLING VALUE do pass, and
#   * the trace has actually converged (_converges)
#
# the machine is moved to the INDIVIDUAL REVIEW list instead of the violation
# list, carrying all of the numbers -- the raw SPPR ratios, the floor, and the
# about-settle ratios -- so a reviewer can see exactly why and disagree. It is
# never silently passed and it is never dropped.
#
# Set this False to score strictly on the ratios as written and let such
# machines fail.
SPPR_FLOOR_LIMITED_AS_REVIEW = True

# The smallest ring amplitude about the settling value that may serve as the
# base of the about-settle ratios, as a fraction of the judged deviation. A
# first peak that lands essentially ON the settling value gives a base near
# zero, and the ratio then divides by noise. 5 % is well below any real first
# ring and well above numerical scatter.
SPPR_SETTLE_MIN_FRAC = 0.05

# How much of the tail defines the settling value, as a fraction of the judged
# window. The mean over the last SPPR_SETTLE_FRAC of the segment.
SPPR_SETTLE_FRAC = 0.10

# >>> WHICH MACHINES THE ROTOR-ANGLE REQUIREMENT APPLIES TO -------------------
#
# SPP Disturbance Performance Requirements Rev 3.0: "MACHINE ROTOR ANGLES shall
# exhibit well damped angular oscillations", to assure "avoidance of loss of
# generator SYNCHRONISM".
#
# An asynchronous machine has no rotor angle in that sense and cannot lose
# synchronism by swinging against the system. PSS/E still writes an ANGL channel
# for the WMOD=1 IBR units this study builds, but what it holds is a converter
# angle that steps with the terminal voltage: it spikes 80-100 degrees at the
# fault and is flat again within a tenth of a second, which is not an angular
# oscillation and is not what SPPR1 and SPPR5 measure.
#
# So they are excluded from the criterion and REPORTED AS EXCLUDED -- named,
# with their deviations, so nothing is hidden. Set False to score them anyway
# (and expect every IBR to "fail").
ANGLE_SKIP_ASYNC = True

# ---- rotor angles RELATIVE TO THE SWING MACHINE --------------------------
# SPP Rev 3.0: "Rotor angle deviations will be calculated relative to the system
# swing machine." add_channels() records the swing machine's angle as
# SWING<bus>_ANGL and evaluate_case subtracts it from every rotor angle.
#
# .out files recorded BEFORE this setting existed have no swing channel. Those
# are scored on ABSOLUTE angles and the report says so on its own line, rather
# than claiming a compliance basis the data cannot support. Re-run to get
# swing-relative angles.
MONITOR_SWING_MACHINE = True

# WHICH swing machine, when the case has more than one -- and this one has many.
# A 35,852-bus MMWG case carries a type-3 bus per island, often several in the
# same island.
#   None = choose automatically, in this priority order:
#            1. the POI's OWN ISLAND. A swing machine in another island shares no
#               synchronising torque with your project, so subtracting its angle
#               is not a relative angle at all -- it is the difference of two
#               unrelated references.
#            2. inside STUDY_AREAS, i.e. the SPP footprint.
#            3. FEWEST HOPS from the POI -- electrically closest to the project.
#            4. largest MBASE, only to break a tie.
#          Distance leads over size deliberately. A 4000 MVA unit eight hundred
#          miles away is a poorer reference for this project's swing behaviour
#          than a nearer machine on the same system: the further away the
#          reference, the more of the inter-area mode ends up in the "relative"
#          angle and the less of it is the project's own response.
#          Every candidate is printed with its area, hops, island membership and
#          MBASE, together with the reason for the choice.
#   <bus>= pin it by hand. Nothing is then guessed.
SWING_BUS = 364003

# How far the swing machine's OWN rotor angle must move across a run before it
# counts as a usable reference. Subtracting a constant cancels out of every
# quantity the rotor-angle criterion uses, so a flatter reference than this is
# reported as unusable rather than as success. 0.10 deg is well below any real
# swing machine's response and well above numerical noise.
SWING_REF_MIN_SPAN_DEG = 0.10

# ---- YOUR SLACK MACHINES -------------------------------------------------
# The type-3 buses reported by the power flow's SWING BUS SUMMARY:
#
#     364003  BR FERRY N   322.0 kV   Pgen 1072.7   Pmax 1302.5
#     590002  OKLAUN1G      24.0 kV   Pgen  401.6   Pmax  670.0
#     590012  MOSES3 G      24.0 kV   Pgen  761.6   Pmax  765.0
#     599956  PNM-DC7      345.0 kV   Pgen  451.2   Pmax 1000.0
#     652585  NB WEST4     230.0 kV   Pgen   31.0   Pmax  250.0
#
# EVERY one of these gets a rotor-angle channel (SWING<bus>_ANGL), not just the
# one chosen as the reference. Three reasons:
#   * the reference is then a choice made at SCORING time, from data already
#     recorded -- changing it does not mean re-running the simulations;
#   * the other slack machines are plotted, so you can see whether the reference
#     is behaving like a reference or swinging itself;
#   * if the chosen one turns out to be unsuitable -- 599956 PNM-DC7 looks like
#     a DC-tie equivalent rather than a synchronous machine -- another is there
#     in the same .out.
#
# ORDER MATTERS: it is the preference order used at scoring time when several
# are present. Put the machine you want as the reference first.
# [] falls back to pick_swing_machine()'s automatic island/nearest search.
SLACK_GENS = [364003]

# ONE reference machine for EVERY project, or the nearest to each POI separately.
# True  = pick_common_slack() chooses the slack machine nearest to the project
#         set as a whole (fewest hops to the closest POI, from one walk seeded
#         with all four), and every project is scored against THAT machine. A
#         rotor angle only means something against a stated reference, so four
#         projects measured against four different machines cannot be compared
#         with one another or rolled up into one report.
# False = each project falls back to the first of SLACK_GENS present in its .out.
SLACK_REF_COMMON = True

# ---- fault RETAINED-VOLTAGE targets (pu) ---------------------------------
# CRITICAL: with inverter-based (IBR) machines, a faulted bus that reaches EXACTLY
# 0.0 pu makes an inverter model output channel go to +/-Infinity, and PSS/E's channel
# writer cannot format Infinity -> "forrtl severe (66): output statement overflows
# record" (SWCAPT/TBLCNC). Observed directly: a solid dist_bus_fault_2 pulled the POI to
# 0.00000 and crashed. The cure is to never let the faulted bus hit exactly zero -- apply
# every fault through a finite shunt reactance sized to a target retained voltage:
#   * SLG  -> hold ~SLG_TARGET_VPU  (a real single-line-to-ground fault retains voltage)
#   * 3PH  -> hold ~THREEPH_TARGET_VPU: deep dip (severe), but strictly > 0 so no Inf.
# Both use dist_bus_fault (balanced). NOTE (proven on this build): with units=3 its
# VALUES are impedance in OHMS -- the code sizes the fault in pu, then converts with
# the bus impedance base (kV^2/MVAbase) before applying. Passing pu directly made a
# 0.15-"pu" fault behave as 0.15 OHM (~bolted) -> the -0.35E+06 MVar shunt in the log.
# (dist_3phase_bus_fault is PSS/E-35-only; dist_bus_fault_2 gave a full collapse here.)
SLG_TARGET_VPU     = 0.60    # retained voltage for an SLG fault
THREEPH_TARGET_VPU = 0.01    # retained voltage for a 3PH fault (deep but non-zero -> no Inf)

# >>> forrtl-66 EVENT-CAPTURE controls -------------------------------------------
# The crash site (SWCAPT = SWitching CAPTure, TBLCNC = TaBLe CoNCatenation, in
# dstbl.dll = Dynamic Simulation TaBLes) is PSS/E adding a PENDING-SWITCHING-EVENT
# record when a protection model PICKS UP. A relay that picks up right at its
# threshold (VTGTPAT instance 52868905 saw V=0.86 -- marginal) computes a huge/
# near-infinite projected trip time from its curve, and formatting that number
# overflows the fixed-width record. Evidence: crash follows the SAME instance's
# pickup in two separate logs; flat run (no pickups) never crashes; severity,
# channels, scans, study areas all irrelevant -- exactly the pickup-table profile.
FAULT_VIA_SHUNT_DATA = False  # apply the fault as a plain FIXED BUS SHUNT (shunt_data +
                             # FACT) instead of dist_bus_fault. Same physics (same
                             # reactor, same retained voltage) but NO dist_* call, so
                             # PSS/E's disturbance/switching-capture bookkeeping --
                             # where SWCAPT crashed even with output silenced -- is
                             # never invoked. Clearing sets the shunt back to 0.
PSSE_SILENT_RUNS = True   # disable ALL PSS/E progress/alert/report output (option 6)
                          # from fault application to end-of-run; restored afterwards.
                          # If the capture writer skips composing when output is off,
                          # this alone fixes the crash. Costs only console messages --
                          # results/.out/plots unaffected.
DIAG_MILD_FAULT  = False  # DIAGNOSTIC: True -> retain 0.85 pu for every fault so NO
                          # protection model picks up. If that run completes, the
                          # pickup-event table is CONFIRMED as the crash source (then
                          # the offending VTGTPAT record must be fixed in the .dyr).
SLG_AUTOTUNE   = True      # measure the actual response once and correct the fault X so the
                           # retained voltage lands on target (robust to unknown Thevenin Z)
SLG_TOL        = 0.01
SLG_MAX_ITER   = 6
SLG_PEEK_S     = 0.01      # tiny run window (s) used to measure the faulted-bus voltage
                           # while tuning; a few of these (~ms) barely shift the fault start
# dist_bus_fault_2 (true unbalanced SLG) is OFF: on this build a BOLTED L-G collapsed the
# positive-sequence voltage to ~0.0 (a real SLG RETAINS voltage) and triggered the IBR Inf
# overflow. With False the SLG is applied as a balanced fault sized (and autotuned) to hold
# ~SLG_TARGET_VPU at the faulted bus -- i.e. a proper retained-voltage SLG, POI does NOT go
# to zero. Set True again only if you first add a fault impedance so it doesn't bolt to 0.
SLG_TRUE_UNBALANCED = False
FAULT_X_BOLTED   = 0.02    # fallback pu fault reactance if a bus's pre-fault V can't be read
THEVENIN_X_GUESS = 0.10    # assumed Thevenin reactance (pu) for sizing the retained-V fault

# ---- MINUTE IMPEDANCE CHANGES TO THE FAULTED LINES ------------------------
# The third item on SPP's system-adjustment list:
#
#     3. Minute impedance changes to faulted lines to help PSS/E fault analysis
#        numerical stability
#
# WHAT IT IS ABOUT. A line whose series reactance is at or near zero -- a
# breaker tie, a bus-section link, a jumper somebody modelled as a branch rather
# than as a bus merge -- is already a short circuit in the admittance matrix.
# Fault one end of it and the fault is effectively applied to both ends at once;
# trip it while the fault is on and a row of that matrix goes singular. What
# comes out is not a crash but pages of "Network not converged", a solution that
# limps along on the last good iterate, and results that look ordinary. SPP nudge
# those impedances by a very small amount, and say so in the report.
#
# WHAT THIS DOES. Every line a scenario faults or trips is measured before the
# run. Anything below the floor is raised to it, the change is named on the
# console and recorded in SYSTEM_ADJUSTMENTS.txt, and the case goes back to the
# snapshot at the start of the next scenario -- so a nudge never leaks from one
# scenario into another.
#
# APPLIED FROM THE SHARED FAULT LIST, so the base case and the project case
# nudge THE SAME lines by the same amount. An impedance change on one side of a
# comparison only would be reported as something the project did.
#
#   0.0     measure and report, change nothing            <- the default
#   0.0001  raise anything below 1e-4 pu to 1e-4 pu       (SPP's "minute")
#
# The default is off deliberately: changing an impedance changes the case, and
# that has to be a decision rather than a side effect of running the study.
FAULT_LINE_MIN_X_PU = 0.0
# Name every faulted/tripped line whose |X| is under this, whether or not the
# floor above is on. This is the CHECK -- it costs nothing and it is how you
# find out whether the study has the problem at all.
FAULT_LINE_X_WARN_PU = 0.0001
FAULT_LINE_MIN_X_PU = float(_env_num("SPP_FAULT_LINE_MIN_X", FAULT_LINE_MIN_X_PU))
FAULT_LINE_X_WARN_PU = float(_env_num("SPP_FAULT_LINE_X_WARN", FAULT_LINE_X_WARN_PU))

# ---- fine-grained CHANNEL TOGGLES (to isolate the forrtl-66 overflow) -----
# The output-writer overflow happens the instant the fault is applied. The usual
# offender is POI FREQUENCY: bus_frequency_channel = d(angle)/dt, which SPIKES to a
# huge value when a fault steps the bus angle -> the value overflows the .out record.
# So POI FREQ is OFF by default. If it still crashes, bisect with the toggles below
# (turn one group off at a time; the group that stops the crash owns the bad channel).
MONITOR_CHSB_AN   = False   # bulk "CHSB AN" all-machine set. Ran ALWAYS-ON before (survived
                            # every other toggle -> the real reason "all off still crashed").
                            # Keep OFF; named PROJ/POI/SYNC channels cover the SPP criteria.
MONITOR_PROJECT   = True    # project PROJ* P/Q/V (your two IBRs)
MONITOR_POI_VANG  = True    # POI voltage + angle
MONITOR_POI_POWER = True    # MW / MVAR delivered across the POI tie(s) -- the FIRST panel of every plot
MONITOR_POI_FREQ  = True   # POI frequency -- df/dt SPIKES at fault -> usual overflow. Keep OFF.
MONITOR_BUS_VOLTS = True    # bus voltages near POI + in areas (poi_volts / area_volt specs)

# ---- nearby SYNCHRONOUS / conventional generator detection ----------------
# Channel quantity codes: 1=ANGL 2=POWR(PELEC) 3=VARS(QELEC) 4=ETRM(ETERM) 7=SPD 13=VOLT
MONITOR_SYNC_IN_RADIUS = False
SYNC_CENTER_BUS  = POI_BUS
SYNC_RADIUS_HOPS = 5
SYNC_KV_MIN      = 2.0
SYNC_MAX_GENS    = 500
_DETECTED_SYNC   = []

# >>> CHANNEL SAFETY (fixes the fault-time crash while KEEPING SPP-criteria data) -------
#   forrtl: severe (66): output statement overflows record ... TBLCNC/SWCAPT
#   happens when a monitored machine's value goes to INFINITY on a fault and PSS/E can't
#   format it into the .out record -> the whole run hard-aborts. The offenders are the
#   IBR (wind/solar) current-source models; SYNCHRONOUS machines stay bounded.
#
#   AREA_SYNC_ONLY = True  -> monitor the area machines' angle/speed/P/Q/Eterm for
#     SYNCHRONOUS units only (WMOD==0), channeled individually. This is exactly what the
#     SPP angle-damping and no-trip criteria evaluate, and it excludes the IBRs that
#     overflow -> full criteria, no crash.  (This is the recommended setting.)
#   MINIMAL_CHANNELS = True -> even stricter: NO area machine channels at all (project +
#     POI + bus voltages only). Use only if AREA_SYNC_ONLY still crashes.
AREA_SYNC_ONLY   = True
# Print, once per build, what each STUDY_AREAS entry costs in channels and how
# many branch hops it is from the POI -- the evidence for shortening that list.
# It reads the case and changes nothing.
AREA_FOOTPRINT_REPORT = True
AREA_SYNC_MAX    = 1500    # cap on synchronous area machines to channel (20 SPP areas; the build prints the count -- raise if it is hit)
MINIMAL_CHANNELS = False
# SPP wants ROTOR ANGLE for synchronous machines AND SPEED for asynchronous (wind/IBR)
# machines in the study areas. AREA_SYNC_ONLY handles the synchronous side; this adds the
# asynchronous SPEED channel (code 7 only -- speed stays bounded, so it does NOT overflow
# the writer the way IBR P/Q/angle can). Set False if you ever hit an overflow traceable
# to an async speed channel.
MONITOR_ASYNC_SPEED = True    # SPP: speed of asynchronous machines in the study areas (plotted, not scored)
ASYNC_SPEED_MAX     = 1500 # cap on asynchronous machines to channel for SPEED (same rule)

# Other Group 3 project buses (group minus your PROJECT_GENS) -- ALWAYS monitored for
# P/Q/Eterm per SPP, regardless of the synchronous-radius setting.
OTHER_GROUP3_BUSES = [b for b in GROUP3_GEN_BUSES if b not in PROJECT_GEN_BUSES]
# >>> MONITOR_SPECS -- area_mach codes 1,2,3,4,7 mirror Run3 CHSB,AR (ANGL,PELEC,QELEC,ETERM,SPD).
#     'area_mach' is the risky one (machine angle/speed/P/Q overflow when a unit loses sync);
#     it is skipped automatically while MINIMAL_CHANNELS is True. Bus-voltage specs are safe.
MONITOR_SPECS = [
    {"name": "grp3_PQV",  "kind": "buses",  "buses": OTHER_GROUP3_BUSES, "codes": [2, 3, 4]},
    # MONITORED IS NOT THE SAME AS REPORTED, and this clause is about MONITORING:
    # "voltages of five (5) buses away from the POI were monitored and plotted"
    # carries no kV qualifier, so every bus in the radius is channelled -- the
    # project's own collector included, which is exactly what you want to PLOT
    # when reading a fault. Keeping them OUT OF THE VIOLATIONS is a separate
    # job, done where it belongs: _chan_is_bes() in the study and
    # _is_bes_voltage_row() in the comparison both drop sub-100 kV buses from
    # the voltage CRITERIA, because SPP applies those to BES buses only. Setting
    # kv_min here instead would have satisfied the criteria by deleting the
    # plots the clause asks for.
    {"name": "poi_volts", "kind": "radius", "center": POI_BUSES_ALL, "hops": POI_RADIUS_HOPS,
     "kv_min": 0.0,   "codes": [13]},
    # ROTOR ANGLE ONLY for the synchronous machines in the study areas. Their
    # P/Q/Eterm/speed were also recorded -- five channels per machine, capped
    # at 500 machines -- and none of those four appears in any SPP criterion
    # for a remote synchronous unit. The angle is what SPPR1/SPPR5 need.
    # ROTOR ANGLE ONLY for the synchronous machines in the study areas. The
    # clause is precise: "the machine rotor angle for synchronous machines
    # within the study areas were monitored" -- angle, and nothing else. P/Q/
    # Eterm belong to a DIFFERENT clause, which names only the project units and
    # the Group 3 queued projects, not every synchronous machine in twenty-one
    # areas. Recording all four here cost four channels per machine for three
    # quantities no SPP criterion asks of a remote synchronous unit; the angle
    # is what SPPR1/SPPR5 need. P/Q/Eterm for the units that DO need them come
    # from MONITOR_PROJECT (the project's own), cent_mach (everything in the
    # POI's area, new and existing) and the Group 3 IBR path below.
    {"name": "area_mach", "kind": "areas",  "areas": STUDY_AREAS, "kv_min": 0.0,
     "codes": [1]},
    # P, Q AND ETERM for EVERY machine in the CENTRAL area -- the area the POI
    # itself sits in ("central" is resolved to that area number when the case
    # is open; set CENTRAL_AREAS = [534] to pin it by hand). sync_only False:
    # the IBRs in the project's own area are exactly the machines this is for.
    {"name": "cent_mach", "kind": "areas",  "areas": "central", "kv_min": 0.0,
     "codes": [2, 3, 4], "sync_only": False},
    # MONITORED, NOT PLOTTED. The SPP report language is explicit on the split:
    # "voltages of five (5) buses away from the POI ... were monitored and
    # plotted", and "the voltages of all 100 kV and above buses within the
    # study area were monitored". So this stays -- the criteria are checked
    # against every >=100 kV bus in the study areas -- and PLOT_ONLY_SPP_SET
    # keeps the PDFs to the near-POI set (plus any area bus that violates,
    # which is never filtered out).
    {"name": "area_volt", "kind": "areas",  "areas": STUDY_AREAS, "kv_min": AREA_KV_MIN, "codes": [13]},
]
# machine-quantity codes (angle/speed/P/Q/Eterm) that can overflow the output writer
_MACHINE_CODES = {1, 2, 3, 4, 7}

# ---- plotting -------------------------------------------------------------
PLOT_MODE = "all"                                    # "all" | "selected" | "radius"
SELECTED_BUSES = list(GROUP3_GEN_BUSES) + [POI_BUS]  # used when PLOT_MODE="selected"
RADIUS_CENTER_BUS, RADIUS_HOPS, BUS_MIN_KV = POI_BUS, 4, 100
ALWAYS_KEEP_KEYWORDS = ["PROJ", "NPGEN", "POI", "SYNC", "FLT"]  # always plotted
                                                     # ("NPGEN" = the NEW PLANT's own
                                                     #  machines -- P, Q, Eterm, rotor
                                                     #  angle and speed for each unit)
                                                     # ("FLT" = the faulted bus of the
                                                     #  scenario -- never filtered out)
                                                     # ("FLT" = the faulted bus of the
                                                     #  scenario -- never filtered out)
WANT = ["VOLT", "ANGLE", "SPEED", "PELEC", "QELEC", "ETERM"]   # which quantities to plot
PER_PAGE, MAKE_PNG, YSPAN_FRAC = 3, False, 0.01      # INDIVIDUAL panels per PDF page; MAKE_PNG=False (no PNG -> faster); min y-span fraction

# >>> PLOT PERFORMANCE (fixes 0 KB / hours-long PDFs on big runs) ---------------
# With RUN_NPLT small and 30 s sims, each channel has THOUSANDS of points, and
# PLOT_MODE="all" + INDIVIDUAL_KEYWORDS=[] gives ONE panel per channel (hundreds).
# The pure-Python PDF/SVG writer then builds a giant in-memory string and effectively
# hangs (that's the 0 KB *_plots.pdf you saw). Two guards fix it:
#   * PLOT_MAX_POINTS -- stride-sample each trace to at most this many points. For a
#     30 s plot 3000 points is visually identical to 7000+, but draws ~2-10x faster.
#   * PLOT_MAX_PANELS -- cap how many INDIVIDUAL panels are drawn. PROJ/POI/SYNC panels
#     are kept FIRST, then the rest, up to the cap. EVERY channel is still in the CSV,
#     so nothing is lost -- this only bounds the PDF/SVG size.
# >>> THE AREA ON EVERY PLOT LABEL --------------------------------------------
# "542963" is a bus number and nothing else. Whether it sits in the project's
# own area or four areas away decides what a 17 degree swing means and who has
# to do something about it, and the plot was the one place that never said.
# Every panel label and every legend entry now carries "AREA <n> <name>"
# alongside the hop distances. Set False for the older, shorter labels.
PLOT_LABEL_AREA = True

PLOT_MAX_POINTS = 1500    # decimate each trace to <= this many points (was 0=no decimation, the main
                          # slowdown). 1500 is visually fine for a 20 s plot, renders far faster and
                          # shrinks the CSV. Lower (e.g. 800) = faster still; set 0 to keep every point.
PLOT_MAX_PANELS = 0        # 0 = NO CAP. Every channel that passes the keep
#                            filter gets its panel -- nothing is skipped.
#
# SET DELIBERATELY, AND IT IS THE SLOW CHOICE. There is no matplotlib here,
# so each panel is drawn by the pure-Python PDF writer: every trace becomes
# PLOT_MAX_POINTS coordinate pairs formatted into the content stream one at
# a time. With ~7,800 channels that is millions of them per scenario, and it
# is why a PDF takes the time it does.
#
# The cap was the fast lever and it has been given up on purpose: a capped
# PDF drops the tail of the area channels, and the SPP voltage band and
# angle criteria are evaluated across those areas. No verdict would change
# -- the criteria are computed from the .out and never from the PDF -- but
# the plot backing a violation could be missing, and a violation you cannot
# show is not evidence.
#
# THE OTHER LEVER IS THE ONE TO USE. Plot time is set by how many channels
# were RECORDED, not by how many are drawn. Recording fewer -- a higher
# AREA_KV_MIN, a shorter STUDY_AREAS -- makes the .out smaller, the plots
# faster and the memory survivable, all without dropping a single channel
# that was recorded. Capping panels hides data that was already paid for.
                          # PROJ/POI/SYNC + voltages kept first; ALL channels remain in the CSV.

# >>> PROFESSIONAL PLOT SETTINGS -------------------------------------------------
# Y-AXIS FIX: a signal that only moves 1.00->1.02 pu looks like a huge swing when the
# axis auto-scales to exactly [1.00, 1.03]. YMIN_SPAN sets a MINIMUM axis window per
# quantity so small ripples are shown small. e.g. voltage always gets at least a
# 0.10 pu window -> a 0.02 pu wiggle reads as a small ripple, not a cliff.
YMIN_SPAN = {
    "VOLT":  0.10,     # pu   -> voltage axis is at least 0.10 pu tall
    "ETERM": 0.10,     # pu   -> machine terminal voltage
    "ANGLE": 10.0,     # deg  -> rotor angle
    "SPEED": 0.0020,   # pu   -> speed deviation
    "PELEC": 2.2,      # MW
    "QELEC": 1.5,      # MVAr
}
# Friendly y-axis labels (with engineering units) per quantity.
YLABELS = {
    "VOLT":  "Bus Voltage (pu)",     "ETERM": "Terminal Voltage (pu)",
    "ANGLE": "Rotor Angle (deg)",    "SPEED": "Speed Deviation (pu)",
    "PELEC": "Real Power (MW)",      "QELEC": "Reactive Power (MVAr)",
}


def _ylabel_for(cat, title=""):
    """Machine PELEC/QELEC channels are pu on the system MVA base (that is what
       PSS/E records); the POI tie flows are branch channels, in MW and MVAr."""
    _t = str(title or "").upper()
    if ("POI POWR" in _t or "POI VARS" in _t or "INTO THE POI" in _t
            or "POI POWER DELIVERED" in _t):
        if cat == "QELEC" or "POI VARS" in _t:
            return "Reactive Power at POI (MVAr)"
        return "Real Power at POI (MW)"
    return YLABELS.get(cat, cat)
PLOT_MARK_FAULT = True     # draw vertical markers at fault-on / fault-clear on fault plots
PLOT_TITLE      = "DIS2201 SPP Dynamic Stability Study"   # header shown on every page
PLOT_DPI        = 150      # PNG resolution
LEGEND_MAX      = 12       # if a subplot has more traces than this, hide the legend (too cluttered)

# >>> VALUES PRINTED UNDER EACH PANEL ----------------------------------------
# A small table beneath every panel, one row per trace: the value at t=0, the
# minimum and the time it occurred, the maximum and its time, and the value at
# the end of the run. It sits BELOW the plot frame, never over the waveforms, and
# the panel spacing grows to make room for it.
PLOT_SHOW_VALUES     = True    # False = no table (and the legend returns, still below)
PLOT_VALUE_ROWS_MAX  = 12      # cap the rows on a crowded overview panel
PLOT_VALUE_DECIMALS  = 4       # significant figures in the table ("%.4g")

# >>> SYNC / ASYNC TAG ON MACHINE TRACES --------------------------------------
# add_channels() names synchronous machines "GEN<bus>_*" and asynchronous ones
# "AGEN<bus>_SPD", so the distinction is already in the channel name; this puts
