# MADE AT IMPORT, because the run log below is opened at import and everything
# after it assumes these folders exist.
#
# WHEN THE PROCESS HAS NO PROJECT this is "<results>\\dynamics" -- see
# RESULTS_DIR above. Such a folder is not a stray file: it is the results folder
# of a process started without SPP_PROJECT, and it holds that process's log.
_ensure_results_dirs()
LOG_FILE   = os.path.join(LOG_DIR, "DYN_STUDY%s.log" % _WSUF)          # per-worker in parallel mode
EVENTS_LOG = os.path.join(LOG_DIR, "DYN_STUDY_EVENTS%s.log" % _WSUF)
# A real throwaway SINK file to discard unwanted PSS/E output. The Windows "NUL" device
# is rejected on some PSS/E builds ("Open failure. NUL (OpnApplFil/OPNPTI)"), which both
# spams the log AND silently defeats fault-window output suppression -- so route discards
# to this real (constantly-overwritten) file instead. Per-worker so processes don't clash.
NULL_SINK  = os.path.join(LOG_DIR, "_psse_sink%s.txt" % _WSUF)


# >>> ONE LOG FILE PER SCENARIO ----------------------------------------------
# The per-worker DYN_STUDY*.log holds everything that worker ever printed, which
# means one file with 10 scenarios interleaved by relaunches. This adds a SECOND
# destination that is switched to the scenario currently running, so each fault
# also gets its own logs\RUN_<id>.log. Opened in APPEND mode, so if a scenario is
# retried after a crash every attempt lands in the same file, in order.
_SCEN_FH = None


def _scenario_log_open(scen_id):
    """Start (or resume) the per-scenario log. Never raises."""
    global _SCEN_FH
    _scenario_log_close()
    try:
        p = os.path.join(LOG_DIR, "RUN_%s%s.log" % (scen_id, _WSUF))
        _SCEN_FH = open(p, "a", buffering=1)
        _SCEN_FH.write("\n" + "=" * 74 + "\n")
        _SCEN_FH.write(" %s -- attempt started %s\n"
                       % (scen_id, time.strftime("%Y-%m-%d %H:%M:%S")))
        _SCEN_FH.write("=" * 74 + "\n")
    except Exception:
        _SCEN_FH = None


def _scenario_log_close():
    """Close the per-scenario log if one is open. Never raises."""
    global _SCEN_FH
    if _SCEN_FH is not None:
        try:
            _SCEN_FH.write(" -- attempt ended %s\n" % time.strftime("%Y-%m-%d %H:%M:%S"))
            _SCEN_FH.flush(); _SCEN_FH.close()
        except Exception:
            pass
    _SCEN_FH = None


class _Tee(object):
    """Mirror stdout/stderr to BOTH the console and the master log file -- and, while
       a scenario is running, to that scenario's own RUN_<id>.log as well."""
    def __init__(self, fh, *cons): self.fh = fh; self.cons = [c for c in cons if c]
    def write(self, d):
        try: self.fh.write(d); self.fh.flush()
        except Exception: pass
        sf = _SCEN_FH                       # read once: another thread may close it
        if sf is not None:
            try: sf.write(d); sf.flush()
            except Exception: pass
        for c in self.cons:
            try: c.write(d); c.flush()
            except Exception: pass
    def flush(self):
        for s in [self.fh] + self.cons:
            try: s.flush()
            except Exception: pass
    def isatty(self): return False


_LOG_FH = open(LOG_FILE, "w", buffering=1)
_ORIG_OUT, _ORIG_ERR = sys.stdout, sys.stderr
try: sys.stdout = _Tee(_LOG_FH, sys.stdout); sys.stderr = _Tee(_LOG_FH, sys.stderr)
except Exception: pass
open(EVENTS_LOG, "w").close()
try: os.chdir(STUDY_DIR)
except Exception as e: print("[init] chdir failed: %s" % e)

# ---- put PSS/E 34 on the Python path BEFORE importing psse34 ---------------
# PSS/E 34's Python .pyc files are version-locked to the interpreter (PSSPY39 = 3.9,
# PSSPY37 = 3.7, PSSPY27 = 2.7). This bootstrap AUTO-DISCOVERS whichever folder under
# your PSS/E install actually contains psse34.py, preferring the one matching THIS
# interpreter, and prints exactly what it added. Set env PSSE_ROOT to override the
# install location. This works no matter which copy of the script you launch.
def _add_path(d):
    # insert at FRONT so the real PSS/E psspy/psscommon win over any stray copies
    # sitting in the study folder (the script dir is normally sys.path[0]).
    if d and os.path.isdir(d):
        while d in sys.path:
            sys.path.remove(d)
        sys.path.insert(0, d)
        os.environ["PATH"] = d + os.pathsep + os.environ.get("PATH", "")
        return True
    return False

def _bootstrap_psse():
    # Add ONLY the interpreter-matching PSSPY## folder + its PSSBIN. Adding a mismatched
    # PSSPY pulls wrong-version/arch DLLs. PSSBIN has the DLLs; PSSPY## has psspy for THIS
    # Python. For older PSS/E (e.g. 34.5 w/ Python 3.4) the modules may sit in PSSBIN itself.
    import glob as _glob
    pyv = sys.version_info[:2]
    prefer = "PSSPY%d%d" % pyv                     # e.g. PSSPY34 for Python 3.4
    roots = [os.environ.get("PSSE_ROOT", "")]
    for base in (r"C:\Program Files (x86)\PTI", r"C:\Program Files\PTI",
                 r"C:\Program Files (x86)\PTI\PSSE34", r"C:\Program Files\PTI\PSSE34"):
        for pat in ("PSSE3*", "PSSE34*", ""):
            for d in _glob.glob(os.path.join(base, pat)) if pat else [base]:
                if os.path.isdir(d):
                    roots.append(d)
    seen = set()
    avail = []
    for root in roots:
        if not root or root in seen or not os.path.isdir(root):
            continue
        seen.add(root)
        here = [os.path.basename(p) for p in _glob.glob(os.path.join(root, "PSSPY*"))
                if os.path.isdir(p)]
        for h in here:
            avail.append("%s\\%s" % (root, h))
        pdir = os.path.join(root, prefer)
        pbin = os.path.join(root, "PSSBIN")
        if os.path.isdir(pdir):
            _add_path(pdir); _add_path(pbin)
            print("[init] PSS/E: %s (+PSSBIN)  Python %d.%d" % (pdir, pyv[0], pyv[1]))
            return True
    # No matching PSSPY## folder. Last resort: some old installs keep psspy in PSSBIN.
    for root in seen:
        pbin = os.path.join(root, "PSSBIN")
        if os.path.isfile(os.path.join(pbin, "psspy.pyd")) or \
           os.path.isfile(os.path.join(pbin, "psspy.py")):
            _add_path(pbin)
            print("[init] PSS/E: %s (PSSBIN, no %s folder) Python %d.%d"
                  % (pbin, prefer, pyv[0], pyv[1]))
            return True
    print("[init] *** no '%s' folder for Python %d.%d. PSSPY folders actually present:" % (prefer, pyv[0], pyv[1]))
    for a in avail or ["   (none found)"]:
        print("        %s" % a)
    print("        -> launch with the Python version matching one of the above,\n"
          "           or set env PSSE_ROOT to the correct PSS/E install. ***")
    return False
_bootstrap_psse()

# psse34.py is an optional shim; the real API is psspy. Import psse34 if it's there,
# otherwise go straight to psspy (both live under PSSPY## on the path now).
try:
    import psse34
except Exception:
    pass
# ---- STAGGERED START -------------------------------------------------------
# The launcher gives worker i a delay of i x LAUNCH_STAGGER_S so that N PSS/E
# sessions do not all ask the CodeMeter licence runtime in the same second --
# which is what produced "Start Error: CodeMeter runtime system is currently
# busy" boxes on every worker at once. Slept BEFORE psspy is imported.
EXIT_LICENCE_BUSY = 86
try:
    _START_DELAY_S = float((os.environ.get("SPP_START_DELAY_S") or "0").strip() or 0)
except Exception:
    _START_DELAY_S = 0.0
if _START_DELAY_S > 0:
    print("[init] staggered start: waiting %.0f s before starting PSS/E so the licence "
          "requests of the %d workers arrive one at a time (SPP_START_DELAY_S)"
          % (_START_DELAY_S, N_WORKERS))
    sys.stdout.flush()
    time.sleep(_START_DELAY_S)
import psspy, dyntools                                 # PSS/E 34 python API + channel reader

# UNIQUE CHANNEL IDENTIFIERS, ENFORCED AT THE API. Two channels with the same
# identifier in one .out header is a file this build's dyntools cannot decode:
# get_data() raises "sequence item 1: expected str instance, int found" on
# every read, the packed reader can never be calibrated for that channel set
# (calibration needs one dyntools read), and every fault of the study is left
# "could not be read". It happened when a plant bus was channelled under two
# roles, or a study-area machine was also the project's swing/sync pick. The
# second and later uses of an identifier get " #2", " #3"... and the set is
# cleared whenever a case or snapshot is loaded, because that is a new header.
_CHAN_IDS_USED = set()
_CHAN_IDENT_ARG = {"machine_array_channel": 2, "branch_p_and_q_channel": 2,
                   "branch_p_channel": 2, "branch_mva_channel": 2,
                   "voltage_and_angle_channel": 1, "voltage_channel": 1,
                   "bus_frequency_channel": 1, "var_channel": 1, "state_channel": 1}


def _uniq_chan_ident(s):
    try:
        base = str(s).strip()
    except Exception:
        return s
    if not base:
        return s
    k = base.upper()
    if k not in _CHAN_IDS_USED:
        _CHAN_IDS_USED.add(k)
        return s
    n = 2
    while ("%s #%d" % (k, n)) in _CHAN_IDS_USED:
        n += 1
    _CHAN_IDS_USED.add("%s #%d" % (k, n))
    stem = base[:32 - len(" #%d" % n)]            # PSS/E keeps 32 characters
    return "%s #%d" % (stem, n)


def _uniq_chan_value(v):
    if isinstance(v, (list, tuple)):
        return [_uniq_chan_ident(x) if isinstance(x, str) else x for x in v]
    return _uniq_chan_ident(v) if isinstance(v, str) else v


def _install_unique_channel_ids():
    for _nm, _ix in _CHAN_IDENT_ARG.items():
        _f = getattr(psspy, _nm, None)
        if _f is None or getattr(_f, "_uniq_wrapped", False):
            continue

        def _mk(f, ix):
            def w(*a, **kw):
                a = list(a)
                if len(a) > ix:
                    a[ix] = _uniq_chan_value(a[ix])
                elif "ident" in kw:
                    kw["ident"] = _uniq_chan_value(kw["ident"])
                return f(*a, **kw)
            w._uniq_wrapped = True
            w.__name__ = getattr(f, "__name__", "channel")
            return w
        setattr(psspy, _nm, _mk(_f, _ix))
    for _nm in ("case", "rstr", "delete_all_plot_channels"):
        _f = getattr(psspy, _nm, None)
        if _f is None or getattr(_f, "_uniq_wrapped", False):
            continue

        def _mk2(f):
            def w(*a, **kw):
                _CHAN_IDS_USED.clear()
                return f(*a, **kw)
            w._uniq_wrapped = True
            w.__name__ = getattr(f, "__name__", "case")
            return w
        setattr(psspy, _nm, _mk2(_f))


try:
    _install_unique_channel_ids()
except Exception as _ue:
    print("[init] unique channel identifiers not installed: %s" % _ue)
try: import redirect; redirect.psse2py()
except Exception as e: print("[init] redirect skipped: %s" % e)

def _up():
    for fn in ("psseversion", "psestatus"):
        f = getattr(psspy, fn, None)
        if f:
            try: r = f(); return (r[0] if isinstance(r, (list, tuple)) else r) == 0
            except Exception: pass
    return False

_GUI = True if IN_PSSE_GUI is True else (False if IN_PSSE_GUI is False else _up())
# THE PLOT CHILD DOES NOT NEED THE ENGINE.
#
# It reads .out files off the disk and draws them. dyntools parses the file
# itself and never asks the engine anything, the packed reader is pure Python,
# and the whole plot path -- plot_missing_outs, make_plots, _score_now --
# contains no psspy call at all (checked: the only top-level psspy uses in this
# file are psseinit and the getdefault* below).
#
# psseinit(150000) allocates a 150,000-bus engine before any of that, which is
# tens of seconds. The plotter draws ONE file and exits, so it paid that on
# every relaunch -- ten files meant ten inits. It also UNMASKS the
# floating-point exceptions, which is the whole reason a NaN in a .out could
# take the process down; not starting the engine avoids that at the source.
#
# SPP_PLOT_PSSE=1 puts it back if anything in the plot path ever does need it.
_PLOT_ONLY = bool((os.environ.get("SPP_PLOT_MISSING") or "").strip())
# SPP_MERGE_ONLY READS parts\ AND WRITES reports\ -- NOTHING ELSE.
#
# It must be safe to run beside a live study, and starting the engine is not:
# psseinit() takes tens of seconds, holds a licence slot the running shards
# need, and unmasks the floating-point exceptions this process is careful to
# keep masked. The merge opens no case and no .out, so it needs none of it.
_MERGE_ONLY = MERGE_ONLY
# SCORE WITHOUT THE CASE -- so the .out read fits in a 32-bit process.
#
# A report/scoring shard normally loads the 35,785-bus case (~1 GB in a 32-bit
# address space) and THEN reads a .out. On the heavy diverged files that is
# ~341 MB of Python floats on top of the case, and the two together exceed the
# 2 GB ceiling: the shard dies mid-read, every launch, and the scenario is
# never scored. Nothing in scoring actually needs the live case -- bus kV,
# names, areas, hop distances and the monitoring radius all come from
# BUS_MAP.csv, exactly as the merge already reads them. So this mode skips
# psseinit and the case load in the report role, freeing the ~1 GB the read
# needs. It is honoured only when the map is on disk (an earlier run wrote it);
# without the map there is nothing to score against, so the case is loaded as
# before. Opt-in via SPP_SCORE_NO_CASE / the launcher's SCORE_NO_CASE.
def _score_no_case_ok():
    if not _env_bool("SPP_SCORE_NO_CASE", False):
        return False
    if str(os.environ.get("SPP_ROLE") or "").strip() != "report":
        return False
    # _bus_map_path() is defined further down; compute the same path inline so
    # this can run at import time without creating the flags\ folder as a side
    # effect. RESULTS_DIR is already set above.
    try:
        return os.path.isfile(os.path.join(RESULTS_DIR, "flags", "BUS_MAP.csv"))
    except Exception:
        return False
_SCORE_NO_CASE = _score_no_case_ok()
if _SCORE_NO_CASE and not _env_bool("SPP_PLOT_PSSE", False):
    print("[init] SCORE_NO_CASE -- NOT starting the PSS/E engine; scoring reads "
          "bus kV / names / adjacency from BUS_MAP.csv so the .out read has the "
          "full address space (32-bit memory fix)")
    _GUI = True
elif (_PLOT_ONLY or _MERGE_ONLY) and not _env_bool("SPP_PLOT_PSSE", False):
    print("[init] %s -- NOT starting the PSS/E engine "
          "(nothing on this path calls it; SPP_PLOT_PSSE=1 restores it)"
          % ("merge-only process" if _MERGE_ONLY else "plot-only process"))
    _GUI = True                    # 'do not initialise', same as an open GUI
elif _GUI:
    print("[init] PSS/E already running -- skipping psseinit()")
else:
    try:
        psspy.psseinit(150000)                        # 150000-bus engine (matches Run1/Run2)
    except Exception as e:
        _msg = str(e)
        if re.search(r"codemeter|licen[cs]e|start error|busy", _msg, re.I):
            # THE LICENCE RUNTIME REFUSED US. Nothing in this process can run,
            # so say so and leave with a code the launcher knows: it relaunches
            # after a pause and charges no scenario attempt (none was reached).
            print("[init] *** PSS/E COULD NOT START: %s" % _msg)
            print("[init]     the CodeMeter licence runtime refused the request -- exiting "
                  "rc=%d so the launcher retries after a pause" % EXIT_LICENCE_BUSY)
            sys.stdout.flush()
            os._exit(EXIT_LICENCE_BUSY)
        print("[init] psseinit raised (%s)" % _msg); _GUI = True

# ---------------------------------------------------------------------------
# RE-MASK THE FLOATING-POINT EXCEPTIONS PSS/E UNMASKS
# ---------------------------------------------------------------------------
# psseinit() unmasks the x87/SSE invalid-operation exception for the process.
# After that call, ANY code in this process that so much as widens a
# signalling NaN from float32 to float64 traps -- including plain Python:
#
#     Invalid Floating-Point number.
#     Image              PC        Routine   Line  Source
#     python34.dll       706917A9  Unknown Unknown Unknown
#     ... every frame in python34.dll ...
#
# Note where that stack is. Not in a PSS/E solver DLL and not in dyntools --
# it is the CPython eval loop. The trap was raised by our own byte screen, by
# struct.unpack('<f') widening a NaN word out of the file it was screening
# FOR NaN. The screen written to keep non-finite values away from PSS/E was
# itself dying on them.
#
# Two things fix that, and both are applied. The screens no longer build a
# float from any word they have not already proved finite (see
# out_scan_nonfinite and _nan_sanitise_copy), and the exception mask is put
# back here so a stray widening anywhere else cannot take the process down.
#
# _controlfp_s is the CRT's own control-word call and is per THREAD, so it is
# re-applied before each read rather than once at startup: PSS/E re-unmasks
# on some API calls, and a read that happens on another thread never saw the
# startup call at all.
_MCW_EM = 0x0008001F                   # the mask bits for all six exceptions

def _fp_mask_exceptions():
    """Mask every FP exception on THIS thread. True if the mask was applied."""
    try:
        import ctypes
        cur = ctypes.c_uint(0)
        for dll in ("msvcr100", "msvcr110", "msvcrt"):
            try:
                lib = ctypes.CDLL(dll + ".dll")
            except Exception:
                continue
            fn = getattr(lib, "_controlfp_s", None)
            if fn is None:
                continue
            # _controlfp_s(&current, new, mask): setting the mask bits to 1
            # means "masked" -- the exception sets a flag instead of trapping.
            if fn(ctypes.byref(cur), ctypes.c_uint(_MCW_EM),
                  ctypes.c_uint(_MCW_EM)) == 0:
                return True
    except Exception:
        pass
    return False

_FP_MASKED = _fp_mask_exceptions()
if _FP_MASKED:
    print("[init] floating-point exceptions re-masked "
          "(psseinit unmasks them process-wide; a NaN in a .out would "
          "otherwise trap inside plain Python)")
else:
    print("[init] could not re-mask floating-point exceptions -- the byte "
          "screens never build a float from a non-finite word, so a NaN .out "
          "is still handled, but PSS/E's own reader remains fragile")



# ---------------------------------------------------------------------------
# NON-INTERACTIVE STDIN  (prevents any line-mode deck from STALLING the terminal)
# ---------------------------------------------------------------------------
# DISABLE_STDIN_REDIRECT now lives in PART 12 at the top of the file.
class _BlankStdin(object):
    """A stdin replacement that always yields an empty line (an <Enter>)."""
    def readline(self, *a, **k): return "\n"
    def read(self, *a, **k):     return "\n"
    def readlines(self, *a, **k): return ["\n"]
    def __iter__(self):          return self
    def __next__(self):          return "\n"
    next = __next__
    def isatty(self):            return False
    def flush(self):             pass
    def close(self):             pass
def _install_noninteractive_stdin():
    if DISABLE_STDIN_REDIRECT or _GUI:
        return
    try:
        sys.stdin = _BlankStdin()
    except Exception as e:
        print("[init] sys.stdin replace skipped (%s)" % e)
    try:
        import tempfile
        fd, path = tempfile.mkstemp(suffix=".ans", prefix="psse_stdin_")
        os.write(fd, ("\n" * 20000).encode()); os.close(fd)
        f = open(path, "rb"); os.dup2(f.fileno(), 0)
    except Exception as e:
        print("[init] fd0 redirect skipped (%s)" % e)
_install_noninteractive_stdin()

# These are only ever passed BACK to psspy, so a process that makes no psspy
# call does not need real ones -- and without psseinit they may not be
# available. The literals are PSS/E's own defaults.
try:
    _i = psspy.getdefaultint(); _f = psspy.getdefaultreal(); _s = psspy.getdefaultchar()
except Exception:
    _i, _f, _s = 2147483647, 1.0e35, " "
