def _xl_esc(v):
    return (str(v).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            .replace('"', "&quot;"))


def _xl_col(n):
    """0 -> A, 26 -> AA."""
    out = ""
    n += 1
    while n:
        n, r = divmod(n - 1, 26)
        out = chr(65 + r) + out
    return out


def _xl_cell(col, row, value, style):
    ref = "%s%d" % (_xl_col(col), row)
    st = ' s="%d"' % style if style else ""
    if value is None or value == "":
        return '<c r="%s"%s/>' % (ref, st)
    # NUMBERS AS NUMBERS. Stored as text, a voltage column sorts 1.2 above 1.19
    # and the filter offers "text filters" rather than "greater than" -- which
    # is most of the reason to produce a spreadsheet at all.
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return '<c r="%s"%s><v>%s</v></c>' % (ref, st, repr(value))
    return ('<c r="%s"%s t="inlineStr"><is><t xml:space="preserve">%s</t></is></c>'
            % (ref, st, _xl_esc(value)))


def _xl_legend_sheet(legend, title_rows):
    """The Key sheet: one row per colour, IN that colour.

       Its own sheet rather than a block above the table, because a legend in
       rows 1-6 pushes the header to row 7 -- and then the frozen pane and the
       filter, both of which are defined against row 1, describe the legend
       instead of the data."""
    xml = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
           '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">',
           '<cols><col min="1" max="1" width="26" customWidth="1"/>',
           '<col min="2" max="2" width="62" customWidth="1"/></cols>',
           '<sheetData>']
    n = 0
    for line in title_rows:
        n += 1
        xml.append('<row r="%d">%s</row>' % (n, _xl_cell(0, n, line, 1 if n == 1 else 0)))
    n += 1
    xml.append('<row r="%d"/>' % n)
    for style, colour, meaning in legend:
        n += 1
        xml.append('<row r="%d">%s%s</row>'
                   % (n, _xl_cell(0, n, colour, style),
                      _xl_cell(1, n, meaning, style)))
    xml.append("</sheetData></worksheet>")
    return "".join(xml)


def _xl_sheet_xml(header, rows, widths=None, style_of=None, first=False):
    """One worksheet: coloured header, frozen top row, filter on every column."""
    ncol = len(header)
    xml = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
           '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">',
           '<sheetViews><sheetView workbookViewId="0"%s>'
           % (' tabSelected="1"' if first else ""),
           '<pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/>',
           '</sheetView></sheetViews>']
    if widths:
        xml.append("<cols>")
        for i, w in enumerate(widths[:ncol]):
            xml.append('<col min="%d" max="%d" width="%d" customWidth="1"/>'
                       % (i + 1, i + 1, w))
        xml.append("</cols>")
    xml.append("<sheetData>")
    xml.append('<row r="1">')
    for i, h in enumerate(header):
        xml.append(_xl_cell(i, 1, h, 1))
    xml.append("</row>")
    for n, row in enumerate(rows, start=2):
        st = style_of(row) if style_of else 0
        xml.append('<row r="%d">' % n)
        for i in range(ncol):
            xml.append(_xl_cell(i, n, row[i] if i < len(row) else "", st))
        xml.append("</row>")
    xml.append("</sheetData>")
    xml.append('<autoFilter ref="A1:%s%d"/>' % (_xl_col(ncol - 1), len(rows) + 1))
    xml.append("</worksheet>")
    return "".join(xml)


def _xl_sheet_to_file(fpath, header, rows, widths=None, style_of=None, first=False):
    """_xl_sheet_xml, written STRAIGHT TO A FILE a row at a time.

       _xl_sheet_xml returns the whole sheet as one string. For the 'Transient
       voltage' sheet -- 758,676 rows x 17 cells for one side of SantaFe --
       that string is ~400 MB, built by joining a list of ~13 million pieces,
       inside a 32-bit python with 2 GB for everything. That allocation is
       what raised the out-of-memory box, and the workbook was then either
       missing or written short. Nothing here is ever larger than one row; the
       zip picks the file up from disk. Same XML, same styles, same filter."""
    import io as _io
    ncol = len(header)
    n_rows = 0
    with _io.open(fpath, "w", encoding="utf-8", newline="") as fh:
        fh.write('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                 '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
                 '<sheetViews><sheetView workbookViewId="0"%s>'
                 '<pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/>'
                 '</sheetView></sheetViews>' % (' tabSelected="1"' if first else ""))
        if widths:
            fh.write("<cols>")
            for i, w in enumerate(widths[:ncol]):
                fh.write('<col min="%d" max="%d" width="%d" customWidth="1"/>' % (i + 1, i + 1, w))
            fh.write("</cols>")
        fh.write("<sheetData>")
        fh.write('<row r="1">' + "".join(_xl_cell(i, 1, h, 1) for i, h in enumerate(header)) + "</row>")
        n = 1
        for row in rows:
            n += 1
            st = style_of(row) if style_of else 0
            fh.write('<row r="%d">' % n
                     + "".join(_xl_cell(i, n, row[i] if i < len(row) else "", st) for i in range(ncol))
                     + "</row>")
        n_rows = n - 1
        fh.write("</sheetData>")
        fh.write('<autoFilter ref="A1:%s%d"/>' % (_xl_col(ncol - 1), n_rows + 1))
        fh.write("</worksheet>")
    return n_rows


def _xl_sheet_name(name):
    """Excel refuses : \\ / ? * [ ] in a sheet name, and more than 31 characters."""
    out = "".join(("-" if ch in ":\\/?*[]" else ch) for ch in str(name))
    return out[:31] or "Sheet"


def write_xlsx_multi(path, sheets, legend=None, title_rows=None):
    """A workbook of several sheets, plus the colour key as the last one.

       sheets: [(name, header, rows, widths, style_of)] -- style_of(row) returns
       a style index, or None for plain rows. Kept as a callback so the
       colouring rule lives with the report that knows what the rows mean.

       ONE sheet of 1,600 element-level rows is a data dump: everything is in it
       and nothing stands out. The same rows split by the question they answer --
       what must be acted on, what was already broken, what was not compared --
       is the same data and a report someone can act on."""
    import zipfile
    import tempfile
    import shutil

    # EVERY DATA SHEET IS STREAMED TO A TEMP FILE, never held as one string --
    # see _xl_sheet_to_file. `parts` holds (name, xml_text) for the small Key
    # sheet and (name, ("file", path)) for the rest; the zip reads the files.
    _tmpdir = tempfile.mkdtemp(prefix="xlsx_", dir=os.path.dirname(os.path.abspath(path)) or None)
    parts = []
    try:
        for i, sh in enumerate(sheets):
            name, header, rows, widths, style_of = (list(sh) + [None, None])[:5]
            _fp = os.path.join(_tmpdir, "sheet%d.xml" % (i + 1))
            _xl_sheet_to_file(_fp, header, rows, widths, style_of, first=(i == 0))
            parts.append((_xl_sheet_name(name), ("file", _fp)))
        parts.append(("Key", _xl_legend_sheet(legend or [], title_rows or [])))

        ct = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
              '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">',
              '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>',
              '<Default Extension="xml" ContentType="application/xml"/>',
              '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>']
        wb = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
              '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"',
              ' xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">',
              '<sheets>']
        rels = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
                '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">']
        for i, (name, _xml) in enumerate(parts, start=1):
            ct.append('<Override PartName="/xl/worksheets/sheet%d.xml" ContentType='
                      '"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>' % i)
            wb.append('<sheet name="%s" sheetId="%d" r:id="rId%d"/>'
                      % (_xl_esc(name), i, i))
            rels.append('<Relationship Id="rId%d" Type="http://schemas.openxmlformats.org'
                        '/officeDocument/2006/relationships/worksheet" Target="worksheets'
                        '/sheet%d.xml"/>' % (i, i))
        ct.append('<Override PartName="/xl/styles.xml" ContentType="application/vnd.'
                  'openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>')
        wb.append("</sheets></workbook>")
        rels.append('<Relationship Id="rId%d" Type="http://schemas.openxmlformats.org'
                    '/officeDocument/2006/relationships/styles" Target="styles.xml"/>'
                    % (len(parts) + 1))
        rels.append("</Relationships>")

        # allowZip64: a 700k-row sheet is well past 2 GB uncompressed across
        # the archive's own accounting on some versions; the flag costs nothing.
        z = zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED, allowZip64=True)
        try:
            z.writestr("[Content_Types].xml", "".join(ct))
            z.writestr("_rels/.rels", _XL_RELS)
            z.writestr("xl/workbook.xml", "".join(wb))
            z.writestr("xl/_rels/workbook.xml.rels", "".join(rels))
            z.writestr("xl/styles.xml", _XL_STYLES)
            for i, (_name, xml) in enumerate(parts, start=1):
                if isinstance(xml, tuple) and xml and xml[0] == "file":
                    z.write(xml[1], "xl/worksheets/sheet%d.xml" % i)
                else:
                    z.writestr("xl/worksheets/sheet%d.xml" % i, xml)
        finally:
            z.close()
    finally:
        shutil.rmtree(_tmpdir, ignore_errors=True)
    return path


def write_xlsx(path, header, rows, widths=None, style_of=None, legend=None,
               title_rows=None):
    """One data sheet plus the colour key -- the single-sheet form, unchanged.

       Every existing caller writes this shape; it is now one sheet handed to
       write_xlsx_multi() rather than a second implementation of the same thing."""
    return write_xlsx_multi(path, [("Comparison", header, rows, widths, style_of)],
                            legend=legend, title_rows=title_rows)


def _collector_rows():
    """This project's collector rows, after the scale multipliers are folded in.

       Returns [(gen, i, j, ckt, R or None, X or None, B or None, rmul, xmul, bmul)].
       A None with a multiplier of 1.0 means "leave this quantity alone"."""
    rows = (COLLECTOR_BRANCHES or {}).get(RUN_PROJECT) or []
    _sc = COLLECTOR_SCALE
    if isinstance(_sc, (int, float)) and not isinstance(_sc, bool):
        # A bare number means every project, all three quantities.
        _sc = {RUN_PROJECT: (float(_sc), float(_sc), float(_sc))}
    elif not isinstance(_sc, dict):
        # {0.2} is a SET, not a scale. Say so here rather than raising
        # 'set has no attribute get' from the middle of a build.
        print("  [coll] COLLECTOR_SCALE must be a number or {project: (r, x, b)} "
              "-- got %r, ignoring it" % type(_sc).__name__)
        _sc = {}
    mul = (_sc or {}).get(RUN_PROJECT) or (1.0, 1.0, 1.0)
    if isinstance(mul, (int, float)) and not isinstance(mul, bool):
        mul = (float(mul), float(mul), float(mul))
    try:
        rmul, xmul, bmul = (float(mul[0]), float(mul[1]), float(mul[2]))
    except Exception:
        print("  [coll] COLLECTOR_SCALE[%r] is not (r, x, b) -- ignored" % RUN_PROJECT)
        rmul = xmul = bmul = 1.0
    # ONE VALUE FOR EVERY COLLECTOR, when z4_cmp_all_con.py asks for it. Applied to
    # every row of every project, over whatever the row says: "the same
    # impedance everywhere" and "this row is different" cannot both hold, and
    # silently honouring the row would make the setting a lie.
    allz = None
    _ca = (os.environ.get("SPP_COLL_ALL") or "").strip()
    if _ca:
        try:
            import json as _json
            _v = list(_json.loads(_ca)) + [None, None, None]
            allz = tuple(_v[:3])
        except Exception as _e:
            print("  [coll] SPP_COLL_ALL could not be read (%s) -- ignored" % _e)
    elif COLLECTOR_ALL is not None:
        _v = list(COLLECTOR_ALL) + [None, None, None]
        allz = tuple(_v[:3])
    # PER-PROJECT VALUES: every collector of this project, unless the row says
    # otherwise. Between the row (most specific) and COLLECTOR_ALL (least).
    projz = None
    _cp = (os.environ.get("SPP_COLL_BY_PROJECT") or "").strip()
    _tbl = None
    if _cp:
        try:
            import json as _json
            _tbl = _json.loads(_cp)
        except Exception as _e:
            print("  [coll] SPP_COLL_BY_PROJECT could not be read (%s) -- ignored" % _e)
    elif COLLECTOR_BY_PROJECT:
        _tbl = COLLECTOR_BY_PROJECT
    if _tbl:
        _v = _tbl.get(RUN_PROJECT)
        if _v is not None:
            _v = list(_v) + [None, None, None]
            projz = tuple(_v[:3])
    out = []
    for row in rows:
        row = list(row)
        # THE CIRCUIT ID IS "1" UNLESS SAID OTHERWISE. A collector is one
        # circuit; writing "1" on every row four times is four chances to typo
        # it, so the row may leave it out entirely --
        #     (765912, 765913, 765914, "1", None, None, None)   with
        #     (765912, 765913, 765914,      None, None, None)   without
        # -- and None or "" mean the same thing. Told apart by TYPE: a circuit
        # id is text, everything else on the row is a number.
        if len(row) >= 4 and not isinstance(row[3], str):
            if len(row) == 6:
                row = row[:3] + [COLLECTOR_DEFAULT_CKT] + row[3:]
            elif row[3] is None and len(row) == 7:
                row[3] = COLLECTOR_DEFAULT_CKT
        row = row + [None] * (7 - len(row))
        gen, i, j, ck, r, x, b = row[:7]
        ck = str(ck).strip() if ck is not None else ""
        # A BUS MAY BE NAMED INSTEAD OF NUMBERED. Numbers differ between decks
        # -- the base case and the cluster case are built by different people
        # from different queue positions -- while "G21-068-GSU1" is the same
        # bus in both. Resolved against the case in memory, so the same table
        # works in either.
        if projz is not None:
            # The ROW wins where it states a value; this fills in the rest.
            r = r if r is not None else projz[0]
            x = x if x is not None else projz[1]
            b = b if b is not None else projz[2]
        if allz is not None:
            r = allz[0] if allz[0] is not None else r
            x = allz[1] if allz[1] is not None else x
            b = allz[2] if allz[2] is not None else b
            # A quantity the one-value setting fixes is not also scaled.
            rmul = 1.0 if allz[0] is not None else rmul
            xmul = 1.0 if allz[1] is not None else xmul
            bmul = 1.0 if allz[2] is not None else bmul
        out.append((gen, _coll_bus(i), _coll_bus(j), ck or COLLECTOR_DEFAULT_CKT,
                    r, x, b, rmul, xmul, bmul))
    return out


def _coll_bus(x):
    """A bus number, from a number or a NAME. 0 when a name cannot be resolved.

       0 rather than an exception: the survey below reports it as "not in the
       case", which is what an unresolvable name means and is more use than a
       traceback."""
    if isinstance(x, int):
        return x
    s = str(x).strip()
    if s.isdigit():
        return int(s)
    try:
        b = resolve_bus(s)
    except Exception:
        b = None
    return int(b) if b else 0


def _brn_find_ckt(i, j, want):
    """The circuit id of the branch between i and j, when `want` is not there.

       A collector written as ck "1" that the case holds as "C1" or " 1" is the
       same physical circuit, and refusing it sends you hunting for a branch
       that is present under a different label. Only ever used when the id
       asked for does not exist, and only when the pair is UNAMBIGUOUS -- two
       circuits between the same buses are two different elements and picking
       one would be a guess."""
    try:
        cks = [str(e[3]).strip() for e in sf_elem_at(int(i)) if int(e[1]) == int(j)]
    except Exception:
        return None
    cks = [c for c in cks if c]
    if not cks:
        return None
    for c in cks:
        if c.strip().lstrip("0") == str(want).strip().lstrip("0"):
            return c
    return cks[0] if len(set(cks)) == 1 else None


def _brn_z(a, z, ck):
    """(R, X) of one branch in one orientation, or None.

       R+jX IS A COMPLEX QUANTITY, and PSS/E splits its branch-data readers by
       return type: brndat returns a REAL (RATEA, CHARG, LENGTH) and brndt2
       returns a COMPLEX (RX, ZJ, ISHNT). Asking brndat for "RX" is not a
       missing branch and not a case problem -- it is the wrong function, and it
       fails identically for every branch in the deck, which is exactly how it
       looked: four collectors, all present in the topology, none readable.

       Both are tried, brndt2 first, so this works whichever way a given build
       spells it."""
    for name in ("brndt2", "brndat"):
        f = getattr(psspy, name, None)
        if f is None:
            continue
        try:
            ie, cx = f(int(a), int(z), str(ck), "RX")
        except Exception:
            continue
        if ie not in (0, None) or cx is None:
            continue
        try:
            return float(cx.real), float(cx.imag)
        except AttributeError:
            # a real came back where a complex was expected -- wrong reader
            continue
    return None


def _brn_in_case(i, j, ck):
    """Is this branch in the case at all, whatever its service status?

       brndat reads the branch's data and can refuse for reasons other than
       absence -- an OUT-OF-SERVICE branch being the one that matters here. The
       branch list is built from the case's own tables, so it answers "does this
       element exist" without caring whether it is closed."""
    try:
        for e in sf_elem_at(int(i)):
            if int(e[1]) == int(j) and str(e[3]).strip() == str(ck).strip():
                return True
    except Exception:
        pass
    return False


def _brn_rxb(i, j, ck):
    """(R, X, B) of a branch as the case holds it, or None if it has no such
       branch. Read back after every change, because a switching call that
       returns ierr=0 having changed nothing is the failure this has to catch."""
    # BOTH ORIENTATIONS. A branch is stored with a from end and a to end, and
    # which is which is a property of the DECK, not of the element: the same
    # circuit is 765913->765914 in one case and 765914->765913 in another. R, X
    # and total charging are identical either way, so reading it backwards is
    # not an approximation -- but asking for the wrong end returns "no such
    # branch", which reads as "not in the case" and is how a branch that is
    # present, in service and correct gets reported as missing.
    for (a, z) in ((int(i), int(j)), (int(j), int(i))):
        rx = _brn_z(a, z, str(ck))
        if rx is None:
            continue
        r, x = rx
        b = None
        # CHARG is a REAL quantity, so it does come from brndat.
        for _fn in ("brndat", "brndt2"):
            f = getattr(psspy, _fn, None)
            if f is None:
                continue
            try:
                ie, v = f(a, z, str(ck), "CHARG")
            except Exception:
                continue
            if ie in (0, None) and v is not None:
                try:
                    b = float(v)
                except (TypeError, ValueError):
                    b = None
                if b is not None:
                    break
        return (r, x, 0.0 if b is None else b)
    return None


def _set_brn_rxb(i, j, ck, r, x, b):
    """Write R/X/B onto one branch, trying each API this build offers.

       Returns the name of the call that took, or "" if none did. What actually
       took is decided by reading the branch back, not by the return code."""
    i, j, ck = int(i), int(j), str(ck)
    # THE ORIENTATION THE CASE STORES IT IN. A change call addressed to the
    # wrong end does nothing and says so with a return code, and the same
    # branch is stored either way round in different decks.
    if _brn_rxb(i, j, ck) is not None:
        try:
            ie, _cx = psspy.brndat(i, j, ck, "RX")
            if ie not in (0, None):
                i, j = j, i
        except Exception:
            i, j = j, i
    tries = []
    if hasattr(psspy, "branch_chng_3"):
        ra = [_f] * 12
        ra[0], ra[1], ra[2] = r, x, b
        tries.append(("branch_chng_3",
                      lambda: psspy.branch_chng_3(i, j, ck, [_i] * 6, ra, [_f] * 12, "")))
    if hasattr(psspy, "branch_chng"):
        rb = [_f] * 12
        rb[0], rb[1], rb[2] = r, x, b
        tries.append(("branch_chng",
                      lambda: psspy.branch_chng(i, j, ck, [_i] * 6, rb)))
    if hasattr(psspy, "branch_data"):
        rc = [_f] * 12
        rc[0], rc[1], rc[2] = r, x, b
        tries.append(("branch_data",
                      lambda: psspy.branch_data(i, j, ck, [_i] * 6, rc)))
    for name, call in tries:
        try:
            call()
        except Exception as e:
            print("  [coll] %s raised on %d-%d ck%s: %s" % (name, i, j, ck, e))
            continue
        now = _brn_rxb(i, j, ck)
        if now and abs(now[0] - r) <= 1e-9 + 1e-6 * abs(r) \
                and abs(now[1] - x) <= 1e-9 + 1e-6 * abs(x) \
                and abs(now[2] - b) <= 1e-9 + 1e-6 * abs(b):
            return name
    return ""


def _fault_line_pairs(fault):
    """[(from, to, ck)] for every line this scenario trips, de-duplicated and
       orientation-insensitive. These are what SPP's report calls the faulted
       lines: the elements the event actually removes."""
    pairs = []
    for ln in (fault.get("trip_lines") or []):
        kv = ln[2] if len(ln) > 2 else fault.get("kv")
        ck = str(ln[3]).strip() if len(ln) > 3 else "1"
        try:
            a, b = resolve_bus(ln[0], kv), resolve_bus(ln[1], kv)
        except Exception:
            continue
        if a and b:
            pairs.append((int(a), int(b), ck))
    for t in (fault.get("trips") or []):
        try:
            pairs.append((int(t[0]), int(t[1]), str(t[2]).strip()))
        except Exception:
            continue
    seen, uniq = set(), []
    for a, b, ck in pairs:
        k = (min(a, b), max(a, b), ck)
        if k in seen:
            continue
        seen.add(k)
        uniq.append((a, b, ck))
    return uniq


def fault_line_impedance_check(fault):
    """SPP system adjustment 3: minute impedance changes to the faulted lines.

       Measures the series reactance of every line this scenario trips. Anything
       under FAULT_LINE_X_WARN_PU is NAMED -- that is the check, and it runs
       whether or not anything is changed. Anything under FAULT_LINE_MIN_X_PU is
       RAISED to it, keeping its sign, and recorded as a system adjustment.

       Called after the snapshot is restored and before strt_2, so the change is
       in the network the dynamics initialise on and is gone again the moment the
       next scenario restores. Nothing is written to any case file."""
    floor = float(FAULT_LINE_MIN_X_PU or 0.0)
    warn = float(FAULT_LINE_X_WARN_PU or 0.0)
    if floor <= 0 and warn <= 0:
        return 0
    pairs = _fault_line_pairs(fault)
    if not pairs:
        return 0
    n_changed = 0
    for a, b, ck in pairs:
        rxb = _brn_rxb(a, b, ck)
        if rxb is None:
            # NOT A LINE IN THIS CASE. A transformer's impedance lives on its
            # winding record and is not reachable through the branch call, and a
            # trip named for the other case is not in this one at all. Both are
            # ordinary; neither is an impedance to change.
            continue
        r, x, bch = rxb
        ax = abs(float(x))
        if warn > 0 and ax < warn:
            print("  [fault-z] %d-%d ck%s has X = %.7f pu -- at or near zero. "
                  "Faulting and tripping a line like this is where PSS/E stops "
                  "converging." % (a, b, ck, x))
        if floor <= 0 or ax >= floor:
            continue
        newx = floor if float(x) >= 0 else -floor
        used = _set_brn_rxb(a, b, ck, r, newx, bch)
        if not used:
            print("  [fault-z]   *** could not change it (no branch call took) "
                  "-- the line is left at %.7f pu ***" % x)
            continue
        n_changed += 1
        print("  [fault-z]   X raised %.7f -> %.7f pu via %s (R and B unchanged)"
              % (x, newx, used))
        adjust_note("faulted-line impedance",
                    "line %d-%d ck%s: X %.7f -> %.7f pu before the fault "
                    "(FAULT_LINE_MIN_X_PU)" % (a, b, ck, x, newx))
    if n_changed:
        # THE FACTORISATION IS NOW STALE. Everything after this solves against
        # the admittance matrix, and it was built from the impedances that have
        # just changed.
        try:
            psspy.fact()
        except Exception as _e:
            print("  [fault-z] could not re-factor after the change (%s)" % _e)
    return n_changed


